print(result)  # Output: 'saint-cyr' (lowercased due to default case_sensitive=False)", "def letter_counter(input: str, ignore_characters: list = ['-', ' '], case_sensitive: bool = False, character_set: str = 'alphabetic', custom_characters: list = [], output_format: str = 'integer') -> str:
    # Validate character_set
    if character_set not in ['alphabetic', 'alphanumeric', 'custom']:
        return 'Error: Invalid character_set value.'

    # Validate output_format
    if output_format not in ['integer', 'text', 'detailed']:
        return 'Error: Invalid output_format value.'

    # Prepare the set of characters to count
    if character_set == 'alphabetic':
        valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
    elif character_set == 'alphanumeric':
        valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789')
    elif character_set == 'custom':
        valid_chars = set(custom_characters)

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        valid_chars = set(char.lower() for char in valid_chars)

    # Count letters excluding ignored characters
    count = 0
    detailed_count = {}
    for char in input:
        if char in ignore_characters:
            continue
        if char in valid_chars:
            count += 1
            if output_format == 'detailed':
                if char in detailed_count:
                    detailed_count[char] += 1
                else:
                    detailed_count[char] = 1

    # Format the output
    if output_format == 'integer':
        return str(count)
    elif output_format == 'text':
        return f'The string contains {count} valid characters.'
    elif output_format == 'detailed':
        return str(detailed_count)

