# Expected output: {'first_name': 'Michele'}", "def count_characters(input, ignore_characters=None, ignore_position=None, case_sensitive=False, character_types=None, output_format='integer'):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if ignore_characters and not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'All ignore_characters must be strings.'}
    if ignore_position and not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'ignore_position must be either "first" or "last".'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if character_types and not all(ct in ['alphabet', 'digit', 'special'] for ct in character_types):
        return {'error': 'character_types must be "alphabet", "digit", or "special".'}
    if output_format not in ['integer', 'text', 'json']:
        return {'error': 'output_format must be "integer", "text", or "json".'}

    # Initialize character count
    count = 0
    frequency = {}

    # Determine character types to count
    count_alphabet = not character_types or 'alphabet' in character_types
    count_digit = not character_types or 'digit' in character_types
    count_special = not character_types or 'special' in character_types

    # Process input string
    for i, char in enumerate(input):
        # Ignore specified positions
        if ignore_position:
            if 'first' in ignore_position and i == 0:
                continue
            if 'last' in ignore_position and i == len(input) - 1:
                continue

        # Ignore specified characters
        if ignore_characters and char in ignore_characters:
            continue

        # Check character types
        if count_alphabet and char.isalpha():
            if not case_sensitive:
                char = char.lower()
            count += 1
            frequency[char] = frequency.get(char, 0) + 1
        elif count_digit and char.isdigit():
            count += 1
            frequency[char] = frequency.get(char, 0) + 1
        elif count_special and not char.isalnum():
            count += 1
            frequency[char] = frequency.get(char, 0) + 1

    # Return result in specified format
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'Total count: {count}'
    elif output_format == 'json':
        return {'total_count': count, 'frequency': frequency}

# Example usage based on the question
result = count_characters(input='Michele', character_types=['alphabet'], output_format='integer')
print(result)  # Output: 7", "def advanced_arithmetic_calculator(operation, operands, output_format='integer', precision=2, error_handling='ignore'):
    # Validate operation
    if operation not in ['add', 'subtract', 'multiply', 'divide', 'modulus', 'exponentiate']:
        return {'error': 'Invalid operation specified.'}
    # Validate operands
    if len(operands) < 2:
        return {'error': 'At least two operands are required.'}
    # Perform operation
    try:
        if operation == 'add':
            result = sum(operands)
        elif operation == 'subtract':
            result = operands[0] - sum(operands[1:])
        elif operation == 'multiply':
            result = 1
            for num in operands:
                result *= num
        elif operation == 'divide':
            result = operands[0]
            for num in operands[1:]:
                if num == 0:
                    if error_handling == 'ignore':
                        return None
                    elif error_handling == 'warn':
                        print('Warning: Division by zero encountered.')
                        return None
                    elif error_handling == 'strict':
                        raise ZeroDivisionError('Division by zero encountered.')
                result /= num
        elif operation == 'modulus':
            result = operands[0]
            for num in operands[1:]:
                result %= num
        elif operation == 'exponentiate':
            result = operands[0]
            for num in operands[1:]:
                result **= num
        # Format result
        if output_format == 'integer':
            return int(result)
        elif output_format == 'float':
            return round(float(result), precision)
        elif output_format == 'string':
            return str(result)
    except Exception as e:
        return {'error': str(e)}

# Example usage for the question 'How many more is 9 than 7?'
