# print(result)  # Expected output: 'William'", "def string_length_counter(input, ignore_characters=None, count_characters=None, ignore_position=None, case_sensitive=False, output_format='integer'):
    """
    Counts the number of characters in the provided strings with various options.
    """
    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 10:
        return {'error': 'Input must be a list of 1 to 10 strings.'}

    # Initialize total count
    total_count = 0
    detailed_report = []

    # Process each string
    for string in input:
        if not case_sensitive:
            string = string.lower()
            if ignore_characters:
                ignore_characters = [char.lower() for char in ignore_characters]
            if count_characters:
                count_characters = [char.lower() for char in count_characters]

        # Apply ignore_characters
        if ignore_characters:
            string = ''.join([char for char in string if char not in ignore_characters])

        # Apply ignore_position
        if ignore_position:
            if 'first' in ignore_position:
                string = string[1:]
            if 'last' in ignore_position:
                string = string[:-1]
            if 'even' in ignore_position:
                string = ''.join([char for i, char in enumerate(string) if i % 2 != 0])
            if 'odd' in ignore_position:
                string = ''.join([char for i, char in enumerate(string) if i % 2 == 0])

        # Count characters
        count = len(string)
        total_count += count

        # Count specific characters separately
        specific_counts = {}
        if count_characters:
            for char in count_characters:
                specific_counts[char] = string.count(char)

        # Add to detailed report
        detailed_report.append({'string': string, 'count': count, 'specific_counts': specific_counts})

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total character count: {total_count}'
    elif output_format == 'detailed_report':
        return detailed_report
    else:
        return {'error': 'Invalid output format specified.'}

# Example usage based on the question
result = string_length_counter(['William'], output_format='integer')
# The result should be 7, as 'William' has 7 letters.", "def extract_first_name(full_name: str, trim_spaces: bool = True, handle_prefixes: bool = False, handle_middle_names: bool = False, handle_suffixes: bool = False, international_format: bool = False, output_case: str = 'titlecase') -> str:
    """
    Extracts the first name from a full name string based on specified parameters.

    Parameters:
    - full_name (str): The full name from which the first name is to be extracted.
    - trim_spaces (bool): Whether to trim extra spaces from the input. Defaults to True.
    - handle_prefixes (bool): Whether to handle common prefixes like 'Dr.', 'Mr.', 'Ms.'. Defaults to False.
    - handle_middle_names (bool): Whether to handle middle names or initials. Defaults to False.
    - handle_suffixes (bool): Whether to handle common suffixes like 'Jr.', 'Sr.', 'III'. Defaults to False.
    - international_format (bool): Whether to support international name formats. Defaults to False.
    - output_case (str): The case format for the output first name. Options are 'uppercase', 'lowercase', 'titlecase'. Defaults to 'titlecase'.

    Returns:
    - str: The extracted first name in the specified case format.
    """
    if not isinstance(full_name, str):
        raise ValueError("The full_name must be a string.")

    # Trim spaces if required
    if trim_spaces:
        full_name = ' '.join(full_name.split())

    # Split the name into parts
    name_parts = full_name.split()

    # Handle prefixes if required
    if handle_prefixes and name_parts[0].endswith('.'):  # Assuming prefixes end with a period
        name_parts = name_parts[1:]

    # Extract the first name
    first_name = name_parts[0] if name_parts else ''

    # Handle middle names if required
    if handle_middle_names and len(name_parts) > 1:
        first_name = name_parts[0]  # Still the first name, but could be more complex logic

    # Handle suffixes if required
    if handle_suffixes and len(name_parts) > 1:
        # Logic to remove suffixes if needed
        pass

    # Adjust case format
    if output_case == 'uppercase':
        first_name = first_name.upper()
    elif output_case == 'lowercase':
        first_name = first_name.lower()
    elif output_case == 'titlecase':
        first_name = first_name.title()
    else:
        raise ValueError("Invalid output_case. Choose from 'uppercase', 'lowercase', 'titlecase'.")

    return first_name

