                result /= num
        elif operation == 'modulus':
            result = numbers[0]
            for num in numbers[1:]:
                result %= num
        elif operation == 'exponent':
            result = numbers[0]
            for num in numbers[1:]:
                result **= num

        # Apply precision
        result = round(result, precision)
        return {'result': result}
    except Exception as e:
        return {'error': str(e)}

