    """
    Extract the first digit from a numerical input string, considering various formats and options.
    """
    import re

    # Error handling for invalid output_format
    if output_format not in ['string', 'integer', 'json']:
        return {'error': 'Invalid output_format specified.'}

    # Handle currency symbols if required
    if handle_currency:
        number = re.sub(r'[\$,]', '', number)

    # Handle scientific notation if required
    if scientific_notation:
        number = re.sub(r'e[+-]?\d+', '', number, flags=re.IGNORECASE)

    # Remove sign if ignore_sign is True
    if ignore_sign:
        number = number.lstrip('-+')

    # Remove leading zeros if ignore_leading_zeros is True
    if ignore_leading_zeros:
        number = number.lstrip('0')

    # Find the first digit
    match = re.search(r'\d', number)
    if not match:
        return {'error': 'No digit found in the input.'}

    first_digit = match.group(0)

    # Format the output
    if output_format == 'string':
        return first_digit
    elif output_format == 'integer':
        return int(first_digit)
    elif output_format == 'json':
        return {
            'first_digit': first_digit,
            'original_input': number,
            'ignore_sign': ignore_sign,
            'ignore_leading_zeros': ignore_leading_zeros,
            'handle_currency': handle_currency,
            'scientific_notation': scientific_notation
        }

