# print(result)  # Expected output: {'date_of_birth': '28 August 1837'}", "def date_incrementer(input_date, increment_days=0, increment_hours=0, increment_minutes=0, output_format='YYYY-MM-DDTHH:MM:SS', time_zone='UTC', calendar_system='Gregorian'):
    from datetime import datetime, timedelta
    import pytz

    # Validate calendar system
    if calendar_system not in ['Gregorian', 'Julian']:
        return {'error': 'Unsupported calendar system. Supported systems are Gregorian and Julian.'}

    # Parse the input date
    try:
        date = datetime.fromisoformat(input_date)
    except ValueError:
        return {'error': 'Invalid date format. Please use ISO 8601 format (YYYY-MM-DDTHH:MM:SS).'}

    # Apply increments
    date += timedelta(days=increment_days, hours=increment_hours, minutes=increment_minutes)

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        date = date.astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone. Please provide a valid time zone.'}

    # Format the output
    if output_format == 'YYYY-MM-DD':
        formatted_date = date.strftime('%Y-%m-%d')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = date.strftime('%d-%m-%Y')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = date.strftime('%m-%d-%Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SS':
        formatted_date = date.strftime('%Y-%m-%dT%H:%M:%S')
    else:
        return {'error': 'Unsupported output format. Please use one of the predefined formats.'}

    return {'result': formatted_date}

# Example usage to answer the question
