    return {'error': 'Unexpected error occurred.'}", "def digit_sum_calculator(number, output_format='integer', include_negative_sign=False, precision=0):
    # Validate the 'number' parameter
    if not isinstance(number, (int, float)):
        return {'error': 'Invalid input: number must be an integer or a floating-point number.'}

    # Handle precision for floating-point numbers
    if isinstance(number, float):
        number = round(number, precision)

    # Convert number to string and handle negative sign
    number_str = str(number)
    if not include_negative_sign and number_str.startswith('-'):
        number_str = number_str[1:]

    # Calculate the sum of digits
    digit_sum = sum(int(char) for char in number_str if char.isdigit())

    # Format the output based on 'output_format'
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return f'The sum of the digits is {digit_sum}.'
    elif output_format == 'json':
        return {'digit_sum': digit_sum}
