                return character
        return "Character not found"", "def extract_last_name(full_name: str, name_format: str = 'western', delimiter: str = ' ', case_sensitive: bool = False, trim_whitespace: bool = True, handle_middle_names: bool = True, compound_last_name: bool = True) -> str:
    """
    Extracts the last name from a full name string based on the specified parameters.

    :param full_name: The full name from which the last name is to be extracted.
    :param name_format: The format of the name, which helps in determining the position of the last name.
    :param delimiter: The character used to separate names.
    :param case_sensitive: Indicates if the extraction should be case sensitive.
    :param trim_whitespace: Indicates if leading and trailing whitespace should be trimmed.
    :param handle_middle_names: Indicates if middle names should be considered in the extraction process.
    :param compound_last_name: Indicates if compound last names should be handled.
    :return: The extracted last name.
    """
    if not full_name:
        return 'Error: full_name is required.'

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Determine the last name based on the name format
    if name_format == 'western':
        last_name = name_parts[-1] if handle_middle_names else name_parts[-1]
    elif name_format == 'eastern':
        last_name = name_parts[0]
    else:
        return 'Error: Unsupported name format.'

    # Handle compound last names
    if compound_last_name and '-' in last_name:
        last_name = last_name.split('-')[-1]

    # Trim whitespace if required
    if trim_whitespace:
        last_name = last_name.strip()

    # Handle case sensitivity
    if not case_sensitive:
        last_name = last_name.lower()

    return last_name

