# print(last_name)  # Output: 'Shakespeare'", "def enhanced_combined_length_calculator(input, output_format='integer', character_encoding='UTF-8', ignore_whitespace=False):
    # Validate input
    if not isinstance(input, list) or len(input) < 1 or not all(isinstance(i, str) for i in input):
        return {'error': 'Invalid input: Must be a list of at least one string.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format: Must be one of integer, text, detailed.'}
    if character_encoding not in ['UTF-8', 'ASCII', 'ISO-8859-1']:
        return {'error': 'Invalid character_encoding: Must be one of UTF-8, ASCII, ISO-8859-1.'}

    # Calculate combined length
    combined_length = 0
    individual_lengths = []
    for string in input:
        if ignore_whitespace:
            string = string.replace(' ', '')
        length = len(string.encode(character_encoding))
        combined_length += length
        individual_lengths.append(length)

    # Prepare output
    if output_format == 'integer':
        return combined_length
    elif output_format == 'text':
        return f'The combined length is {combined_length}.'
    elif output_format == 'detailed':
        average_length = combined_length / len(input)
        return {
            'combined_length': combined_length,
            'average_length': average_length,
            'individual_lengths': individual_lengths
        }

