    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Error handling for date format
    try:
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid input_date format. Expected YYYY-MM-DD.'

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        date_obj = tz.localize(date_obj)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone specified.'

    # Perform the operation
    if operation == 'subtract':
        date_obj -= timedelta(days=days, weeks=weeks)
        date_obj -= relativedelta(months=months, years=years)
    elif operation == 'add':
        date_obj += timedelta(days=days, weeks=weeks)
        date_obj += relativedelta(months=months, years=years)
    elif operation == 'difference':
        if not comparison_date:
            return 'Error: comparison_date is required for difference operation.'
        try:
            comparison_obj = datetime.strptime(comparison_date, '%Y-%m-%d')
            comparison_obj = tz.localize(comparison_obj)
        except ValueError:
            return 'Error: Invalid comparison_date format. Expected YYYY-MM-DD.'
        difference = (date_obj - comparison_obj).days
        return str(difference)
    else:
        return 'Error: Unsupported operation.'

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        return date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        return date_obj.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        return date_obj.strftime('%d-%m-%Y')
    elif output_format == 'ISO8601':
        return date_obj.isoformat()
    else:
        return 'Error: Unsupported output format.'

