    - handle_prefix_suffix (bool): Whether to handle prefixes and suffixes. Defaults to True.
    - output_format (str): The format of the output. Defaults to 'string'.
    - international_format (bool): Whether to support international name formats. Defaults to False.
    - delimiter (str): The delimiter for multiple last names. Defaults to ','.
    - handle_hyphenated_names (bool): Whether to handle hyphenated last names. Defaults to True.

    Returns:
    - str, list, or dict: The extracted last names in the specified format.
    """
    if not isinstance(names, list) or not all(isinstance(name, str) for name in names):
        return {'error': 'Invalid input: names must be a list of strings.'}

    if output_format not in ['string', 'array', 'csv', 'json']:
        return {'error': 'Invalid output format specified.'}

    last_names = []
    for name in names:
        # Split the name into parts
        parts = name.split()

        # Handle prefixes and suffixes
        if handle_prefix_suffix:
            # Example: Remove common prefixes and suffixes
            prefixes = ['Dr.', 'Mr.', 'Mrs.', 'Ms.']
            suffixes = ['Jr.', 'Sr.', 'II', 'III']
            parts = [part for part in parts if part not in prefixes + suffixes]

        # Consider middle names
        if consider_middle_names and len(parts) > 2:
            last_name = parts[-1]
        else:
            last_name = parts[-1] if len(parts) > 1 else parts[0]

        # Handle hyphenated names
        if handle_hyphenated_names and '-' in last_name:
            last_name = last_name.replace('-', ' ')

        last_names.append(last_name)

    # Format the output
    if output_format == 'string':
        return last_names[0] if len(last_names) == 1 else delimiter.join(last_names)
    elif output_format == 'array':
        return last_names
    elif output_format == 'csv':
        return delimiter.join(last_names)
    elif output_format == 'json':
