print(biographical_data_retriever('Trygve Lange-Nielsen', ['date_of_death'], 'generic_database'))", "def date_calculator(input_date, interval, adjust_for_end_of_month=False, calendar_system='Gregorian', time_zone='UTC'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate input_date format
    try:
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid date format. Please use YYYY-MM-DD.'}

    # Validate calendar system
    if calendar_system not in ['Gregorian', 'Julian']:
        return {'error': 'Unsupported calendar system. Please use Gregorian or Julian.'}

    # Validate time zone
    try:
        timezone = pytz.timezone(time_zone)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone. Please use a valid time zone.'}

    # Apply interval adjustments
    days = interval.get('days', 0)
    weeks = interval.get('weeks', 0)
    months = interval.get('months', 0)
    years = interval.get('years', 0)

    # Calculate new date
    new_date = date_obj + timedelta(days=days + weeks * 7)
    new_date += relativedelta(months=months, years=years)

    # Adjust for end of month if necessary
    if adjust_for_end_of_month:
        last_day_of_month = (new_date + relativedelta(day=31)).day
        if new_date.day != last_day_of_month:
            new_date = new_date.replace(day=last_day_of_month)

    # Convert to specified time zone
    new_date = timezone.localize(new_date)

    # Return the calculated date in the specified format
    return {'calculated_date': new_date.strftime('%Y-%m-%d')}

# Example usage based on the question
