    # Validate input types
    if not isinstance(input_string, str):
        return 'Error: input_string must be a string.'
    if not isinstance(case_sensitive, bool):
        return 'Error: case_sensitive must be a boolean.'
    if not isinstance(min_length, int) or min_length < 1:
        return 'Error: min_length must be a positive integer.'
    if not isinstance(include_non_letters, bool):
        return 'Error: include_non_letters must be a boolean.'

    # Adjust string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()

    # Initialize variables
    longest = ''
    current = ''

    # Iterate through the string
    for i, char in enumerate(input_string):
        if include_non_letters or char.isalpha():
            if i == 0 or char >= input_string[i - 1]:
                current += char
            else:
                if len(current) >= min_length and len(current) > len(longest):
                    longest = current
                current = char
        else:
            if len(current) >= min_length and len(current) > len(longest):
                longest = current
            current = ''

    # Final check for the last substring
    if len(current) >= min_length and len(current) > len(longest):
        longest = current

    return longest if longest else 'No valid substring found.'

