    # Define delimiters mapping
    delimiters = {
        'space': ' ',
        'hyphen': '-',
        'comma': ',',
        'semicolon': ';',
        'period': '.'
    }

    # Check if the provided delimiter is valid
    if delimiter not in delimiters:
        raise ValueError("Invalid delimiter. Supported delimiters are: space, hyphen, comma, semicolon, period.")

    # Split the full name based on the specified delimiter
    name_parts = full_name.split(delimiters[delimiter])

    # Handle title stripping if required
    if title_handling == 'strip':
        # Assuming titles are at the start of the name
        if name_parts[0].lower() in ['dr', 'mr', 'ms', 'mrs', 'miss']:
            name_parts = name_parts[1:]

    # Determine the first name based on cultural format
    if cultural_format == 'western':
        first_name = name_parts[0]
    elif cultural_format == 'eastern':
        first_name = name_parts[-1]
    elif cultural_format == 'arabic':
        # Handle 'bin' or 'bint' if present
        if 'bin' in name_parts or 'bint' in name_parts:
            first_name = name_parts[name_parts.index('bin') + 1] if 'bin' in name_parts else name_parts[name_parts.index('bint') + 1]
        else:
            first_name = name_parts[0]
    elif cultural_format == 'hispanic':
        first_name = name_parts[0]
    else:
        raise ValueError("Invalid cultural format. Supported formats are: western, eastern, arabic, hispanic.")

    # Include middle name if required
    if include_middle_name and len(name_parts) > 2:
        first_name += ' ' + name_parts[1]

    # Handle title inclusion if required
    if title_handling == 'include' and name_parts[0].lower() in ['dr', 'mr', 'ms', 'mrs', 'miss']:
        first_name = name_parts[0] + ' ' + first_name

    return first_name

