    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Characters must be a list of single-character strings.'}
    if count_range['end'] is None:
        count_range['end'] = len(input)
    if not (0 <= count_range['start'] < count_range['end'] <= len(input)):
        return {'error': 'Invalid count range specified.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        characters = [c.lower() for c in characters]

    # Initialize count dictionary
    counts = {char: 0 for char in characters}

    # Count characters
    for i, char in enumerate(input):
        if i < count_range['start'] or i >= count_range['end']:
            continue
        if char in ignore_characters:
            continue
        if 'first' in ignore_position and i == 0:
            continue
        if 'last' in ignore_position and i == len(input) - 1:
            continue
        if char in characters:
            counts[char] += 1

    # Prepare output
    if output_format == 'integer':
        return sum(counts.values())
    elif output_format == 'text':
        return ', '.join(f"{char}: {count}" for char, count in counts.items())
    elif output_format == 'detailed_report':
        return counts
    else:
        return {'error': 'Invalid output format specified.'}

