        'all': string.ascii_letters + 'АБВГДЕЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯабвгдежзийклмнопрстуфхцчшщъыьэюя' + 'ΑΒΓΔΕΖΗΘΙΚΛΜΝΞΟΠΡΣΤΥΦΧΨΩαβγδεζηθικλμνξοπρστυφχψω'
    }

    # Handle empty string
    if not input:
        if handle_empty_string == 'error':
            raise ValueError('Input string is empty.')
        elif handle_empty_string == 'null':
            return None
        elif handle_empty_string == 'default_character':
            return ''

    # Select character set
    if character_set not in character_sets:
        raise ValueError('Unsupported character set.')
    valid_chars = character_sets[character_set]

    # Process input
    for char in input:
        if ignore_leading_non_letters and char not in valid_chars:
            continue
        if not case_sensitive:
            char = char.lower()
        if char in valid_chars:
            if output_format == 'character':
                return char
            elif output_format == 'ascii':
                return ord(char)
            elif output_format == 'unicode':
                return f'U+{ord(char):04X}'
            elif output_format == 'hex':
                return hex(ord(char))

    # If no valid character is found
    return None"]

