["def actor_cross_reference(productions, name_variations=False, output_format='list', role_filter=None, date_range=None):
    # Validate productions
    if not isinstance(productions, list) or len(productions) < 2:
        return {'error': 'At least two productions must be provided.'}

    # Validate output_format
