        return {'error': 'Invalid output format. Choose from list, text, or detailed.'}

    # Validate date_range
    if date_range:
        if 'start_date' in date_range and not isinstance(date_range['start_date'], str):
            return {'error': 'Start date must be a string in date format.'}
        if 'end_date' in date_range and not isinstance(date_range['end_date'], str):
            return {'error': 'End date must be a string in date format.'}

    # Simulated logic for finding common actors
    # For demonstration, we assume a predefined set of actors for each production
    production_actors = {
        "Charlotte's Shorts": {'Gary Anthony Williams', 'Actor B', 'Actor C'},
        "Weeds": {'Gary Anthony Williams', 'Actor D', 'Actor E'}
    }

    # Find common actors
    common_actors = set(production_actors.get(productions[0], set()))
    for production in productions[1:]:
        common_actors.intersection_update(production_actors.get(production, set()))

    # Apply role_filter if provided
