print(result)  # Expected output: {'date_of_death': '14 May 1790'}", "def date_calculator(start_date: str, start_time: str = '00:00:00', months_to_add: int = 0, days_to_add: int = 0, years_to_add: int = 0, time_zone: str = 'UTC', output_format: str = 'YYYY-MM-DD') -> str:
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start_date format. Expected YYYY-MM-DD.'

    # Validate start_time format
    try:
        start_time_obj = datetime.strptime(start_time, '%H:%M:%S').time()
    except ValueError:
        return 'Error: Invalid start_time format. Expected HH:MM:SS.'

    # Combine date and time
    start_datetime = datetime.combine(start_date_obj, start_time_obj)

    # Apply time zone
    try:
        tz = pytz.timezone(time_zone)
        start_datetime = tz.localize(start_datetime)
    except pytz.UnknownTimeZoneError:
        return 'Error: Invalid time_zone specified.'

    # Calculate new date
    new_datetime = start_datetime + relativedelta(months=months_to_add, days=days_to_add, years=years_to_add)

    # Format output
    if output_format == 'YYYY-MM-DD':
        return new_datetime.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        return new_datetime.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        return new_datetime.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DD HH:MM:SS':
        return new_datetime.strftime('%Y-%m-%d %H:%M:%S')
    elif output_format == 'MM/DD/YYYY HH:MM:SS':
        return new_datetime.strftime('%m/%d/%Y %H:%M:%S')
    elif output_format == 'DD-MM-YYYY HH:MM:SS':
        return new_datetime.strftime('%d-%m-%Y %H:%M:%S')
    else:
        return 'Error: Invalid output_format specified.'

# Example usage based on the question
