    return {'error': 'Film not found with the specified director and actor criteria.'}", "def date_calculator(start_date, weeks_to_add=0, days_to_add=0, months_to_add=0, years_to_add=0, output_format='YYYY-MM-DD', timezone='UTC'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Validate output_format
    valid_formats = ['YYYY-MM-DD', 'MM/DD/YYYY', 'DD-MM-YYYY', 'DD/MM/YYYY', 'YYYY/MM/DD']
    if output_format not in valid_formats:
        return {'error': 'Invalid output_format. Choose from ' + ', '.join(valid_formats) + '.'}

    # Validate timezone
    try:
        tz = pytz.timezone(timezone)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid timezone. Please provide a valid IANA timezone name.'}

    # Perform date arithmetic
    date_obj += timedelta(weeks=weeks_to_add, days=days_to_add)
    date_obj += relativedelta(months=months_to_add, years=years_to_add)

    # Convert to specified timezone
    date_obj = date_obj.astimezone(tz)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        formatted_date = date_obj.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = date_obj.strftime('%d-%m-%Y')
    elif output_format == 'DD/MM/YYYY':
        formatted_date = date_obj.strftime('%d/%m/%Y')
    elif output_format == 'YYYY/MM/DD':
        formatted_date = date_obj.strftime('%Y/%m/%d')

    return {'result': formatted_date}

