    if not isinstance(handle_middle_names, bool):
        return {'error': 'Invalid input: handle_middle_names must be a boolean.'}
    if not isinstance(cultural_conventions, str):
        return {'error': 'Invalid input: cultural_conventions must be a string.'}
    if not isinstance(initials_handling, bool):
        return {'error': 'Invalid input: initials_handling must be a boolean.'}

    # Define common prefixes and suffixes
    prefixes = ['Mr.', 'Ms.', 'Mrs.', 'Dr.'] if ignore_prefixes else []
    suffixes = ['Jr.', 'Sr.', 'II', 'III'] if ignore_suffixes else []

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Remove prefixes
    if ignore_prefixes:
        name_parts = [part for part in name_parts if part not in prefixes]

    # Remove suffixes
    if ignore_suffixes:
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle cultural conventions (simplified for this example)
    if cultural_conventions == 'Eastern':
        # Eastern naming convention might have the family name first
        first_name_index = 1 if len(name_parts) > 1 else 0
    else:
        # Default to Western naming convention
        first_name_index = 0

    # Extract the first name
    if initials_handling:
        # If handling initials, consider initials as part of the first name
        first_name = name_parts[first_name_index]
    else:
        # Otherwise, ensure the first name is not an initial
        first_name = name_parts[first_name_index] if len(name_parts[first_name_index]) > 1 else ''

    # Handle middle names if required
    if handle_middle_names and len(name_parts) > 2:
        first_name += ' ' + ' '.join(name_parts[1:])

