    # Error handling for incorrect input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(delimiters, list) or not all(isinstance(d, str) for d in delimiters):
        return {'error': 'Invalid input: delimiters must be a list of strings.'}

    # Define common prefixes and suffixes
    prefixes = ['Mr.', 'Mrs.', 'Dr.', 'Ms.'] if handle_prefixes else []
    suffixes = ['Jr.', 'Sr.', 'II', 'III'] if handle_suffixes else []

    # Remove prefixes
    for prefix in prefixes:
        if full_name.startswith(prefix):
            full_name = full_name[len(prefix):].strip()
            break

    # Remove suffixes
    for suffix in suffixes:
        if full_name.endswith(suffix):
            full_name = full_name[:-len(suffix)].strip()
            break

    # Split the name using the provided delimiters
    import re
    delimiter_pattern = '|'.join(map(re.escape, delimiters))
    name_parts = re.split(delimiter_pattern, full_name)

    # Handle middle names
    if handle_middle_names:
        first_name = name_parts[0]
    else:
        first_name = ' '.join(name_parts[:-1]) if multi_part_first_name else name_parts[0]

    # Handle multi-part first names
    if multi_part_first_name and len(name_parts) > 1:
        first_name = name_parts[0] + ' ' + name_parts[1]

    return {'first_name': first_name.strip()}

# Example usage
