# historical_bio_lookup(name='John Manners, 2Nd Duke Of Rutland', fields=['date_of_death'])", "def day_of_week_calculator(date, calendar_system='Gregorian', output_format='full', timezone='UTC', locale='en-US'):
    from datetime import datetime
    import pytz
    import calendar
    from babel.dates import format_date

    # Error handling for date format
    try:
        # Attempt to parse the date
        if '-' in date:
            parsed_date = datetime.strptime(date, '%Y-%m-%d')
        elif '/' in date:
            parsed_date = datetime.strptime(date, '%m/%d/%Y')
        else:
            parsed_date = datetime.strptime(date, '%d-%m-%Y')
    except ValueError:
        return {'error': 'Invalid date format. Please use YYYY-MM-DD, DD-MM-YYYY, or MM/DD/YYYY.'}

    # Error handling for calendar system
    if calendar_system not in ['Gregorian', 'Julian', 'Hebrew', 'Islamic']:
        return {'error': 'Unsupported calendar system. Please choose from Gregorian, Julian, Hebrew, or Islamic.'}

    # Error handling for output format
    if output_format not in ['full', 'abbreviated', 'numeric']:
        return {'error': 'Invalid output format. Please choose from full, abbreviated, or numeric.'}

    # Convert date to the specified timezone
    try:
        timezone_obj = pytz.timezone(timezone)
        localized_date = timezone_obj.localize(parsed_date)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown timezone. Please provide a valid timezone.'}

    # Calculate the day of the week
    day_index = localized_date.weekday()  # Monday is 0 and Sunday is 6
    if output_format == 'numeric':
        return {'day': day_index}
    elif output_format == 'abbreviated':
        day_name = calendar.day_abbr[day_index]
    else:  # full
        day_name = calendar.day_name[day_index]

    # Localize the day name
    localized_day_name = format_date(localized_date, 'EEEE', locale=locale)

    return {'day': localized_day_name if output_format == 'full' else day_name}

# Example usage
result = day_of_week_calculator('22-02-1721', calendar_system='Julian', output_format='numeric')
print(result)  # Expected output: {'day': 22}"]

