# biographical_info_retriever(name='Ömer Kavur', info_type=['date_of_death'])", "def date_calculator(start_date: str, operation: str, value: int, unit: str, output_format: str, time_zone: str = 'UTC', business_days: bool = False) -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Parse the start date
    try:
        date_formats = ['%Y-%m-%d', '%m-%d-%Y', '%d-%m-%Y', '%Y-%m-%dT%H:%M:%S']
        for fmt in date_formats:
            try:
                start_date_obj = datetime.strptime(start_date, fmt)
                break
            except ValueError:
                continue
        else:
            raise ValueError('Invalid date format')
    except Exception as e:
        return f'Error: {str(e)}'

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_obj = tz.localize(start_date_obj)
    except Exception as e:
        return f'Error: Invalid time zone - {str(e)}'

    # Perform the operation
    try:
        if operation == 'add':
            if unit == 'days':
                delta = timedelta(days=value)
            elif unit == 'months':
                delta = relativedelta(months=value)
            elif unit == 'years':
                delta = relativedelta(years=value)
            elif unit == 'hours':
                delta = timedelta(hours=value)
        elif operation == 'subtract':
            if unit == 'days':
                delta = timedelta(days=-value)
            elif unit == 'months':
                delta = relativedelta(months=-value)
            elif unit == 'years':
                delta = relativedelta(years=-value)
            elif unit == 'hours':
                delta = timedelta(hours=-value)
        else:
            raise ValueError('Invalid operation')

        result_date = start_date_obj + delta
    except Exception as e:
        return f'Error: {str(e)}'

    # Format the output date
    try:
        if output_format == 'YYYY-MM-DD':
            result_str = result_date.strftime('%Y-%m-%d')
        elif output_format == 'MM-DD-YYYY':
            result_str = result_date.strftime('%m-%d-%Y')
        elif output_format == 'DD-MM-YYYY':
            result_str = result_date.strftime('%d-%m-%Y')
        elif output_format == 'ISO 8601':
            result_str = result_date.isoformat()
        else:
            raise ValueError('Invalid output format')
    except Exception as e:
        return f'Error: {str(e)}'

    return result_str

# Example usage based on the question
result = date_calculator(start_date='12-05-2005', operation='subtract', value=1, unit='months', output_format='YYYY-MM-DD')
print(result)  # Expected output: '2005-04-12'"]

