    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Error handling for unsupported calendar systems
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': 'Unsupported calendar system'}

    # Error handling for unsupported output formats
    if output_format not in ['YYYY-MM-DD', 'DD-MM-YYYY', 'MM-DD-YYYY', 'ISO-8601']:
        return {'error': 'Unsupported output format'}

    # Parse the start date
    try:
        date_formats = ['%Y-%m-%d', '%d-%m-%Y', '%m-%d-%Y']
        for fmt in date_formats:
            try:
                start_date_parsed = datetime.strptime(start_date, fmt)
                break
            except ValueError:
                continue
        else:
            return {'error': 'Invalid date format'}
    except Exception as e:
        return {'error': str(e)}

    # Apply the interval
    try:
        years = interval.get('years', 0)
        months = interval.get('months', 0)
        weeks = interval.get('weeks', 0)
        days = interval.get('days', 0)

        new_date = start_date_parsed + relativedelta(years=years, months=months) + timedelta(weeks=weeks, days=days)
    except Exception as e:
        return {'error': str(e)}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        new_date = tz.localize(new_date)
    except Exception as e:
        return {'error': 'Invalid time zone'}

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date.strftime('%Y-%m-%d')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date.strftime('%d-%m-%Y')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = new_date.strftime('%m-%d-%Y')
    elif output_format == 'ISO-8601':
        formatted_date = new_date.isoformat()

    return {'result': formatted_date}

