    """
    Extracts the first name from a full name string, considering various parameters.
    """
    import re

    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        raise ValueError('Invalid full_name: must be a non-empty string.')

    # Split the full name using the specified delimiter
    name_parts = full_name.split(name_delimiter)

    # Handle special characters if required
    if handle_special_characters:
        name_parts = [re.sub(r'[^\w\s]', '', part) for part in name_parts]

    # Remove empty parts after splitting
    name_parts = [part for part in name_parts if part]

    # Define lists for titles and suffixes
    titles = ['Mr', 'Mrs', 'Ms', 'Dr'] if not include_titles else []
    suffixes = ['Jr', 'Sr', 'II', 'III'] if not include_suffixes else []

    # Extract the first name
    first_name = None
    for part in name_parts:
        # Skip titles and suffixes if not included
        if part in titles or part in suffixes:
            continue
        first_name = part
        break

    # Handle case sensitivity
    if not case_sensitive and first_name:
        first_name = first_name.capitalize()

    # Return the first name or raise an error if not found
    if first_name:
        return first_name
    else:
        raise ValueError('Could not extract a valid first name from the input.')

