        return {'error': 'Invalid output format.'}

    # Validate sort_direction
    if sort_direction not in ['ascending', 'descending']:
        return {'error': 'Invalid sort direction.'}

    # Validate language_support
    if language_support not in ['english', 'spanish', 'french', 'german']:
        return {'error': 'Unsupported language.'}

    # Prepare the string for sorting
    if not case_sensitive:
        input = input.lower()

    # Sort the characters
    sorted_chars = sorted(input, reverse=(sort_direction == 'descending'))

    # Handle special characters
    if not handle_special_characters:
        sorted_chars = [char for char in sorted_chars if char.isalnum()]

    # Format the output
    if output_format == 'array':
        return sorted_chars
    elif output_format == 'string':
        return ''.join(sorted_chars)
    elif output_format == 'json':
        import json
        return json.dumps(sorted_chars)
    elif output_format == 'csv':
        return ','.join(sorted_chars)

