# print(result)  # Expected output: 'Ridley Scott'", "def name_extractor(full_name: str, part_to_extract: str = 'first_name', ignore_case: bool = False, handle_special_characters: bool = True, name_format: str = 'western', extract_multiple: bool = False):
    # Validate required parameters
    if not full_name or not part_to_extract:
        return {'error': 'Missing required parameters: full_name and part_to_extract are required.'}

    # Validate part_to_extract
    valid_parts = ['first_name', 'last_name', 'middle_name', 'initials', 'suffix']
    if part_to_extract not in valid_parts:
        return {'error': f"Invalid part_to_extract value. Must be one of {valid_parts}."}

    # Split the full_name into individual names if extract_multiple is True
    names = full_name.split(',') if extract_multiple else [full_name]

    # Initialize result list
    results = []

    # Process each name
    for name in names:
        # Handle special characters if required
        if handle_special_characters:
            name = ''.join(e for e in name if e.isalnum() or e.isspace())

        # Split the name based on the format
        name_parts = name.split()
        if name_format == 'eastern':
            # Eastern format typically has last name first
            first_name = name_parts[-1] if len(name_parts) > 1 else name_parts[0]
            last_name = name_parts[0] if len(name_parts) > 1 else ''
        else:  # Default to western
            first_name = name_parts[0] if len(name_parts) > 0 else ''
            last_name = name_parts[-1] if len(name_parts) > 1 else ''

        # Extract the requested part
        if part_to_extract == 'first_name':
            results.append(first_name)
        elif part_to_extract == 'last_name':
            results.append(last_name)
        elif part_to_extract == 'middle_name':
            middle_name = ' '.join(name_parts[1:-1]) if len(name_parts) > 2 else ''
            results.append(middle_name)
        elif part_to_extract == 'initials':
            initials = ''.join([part[0] for part in name_parts if part])
            results.append(initials)
        elif part_to_extract == 'suffix':
            # Assuming suffix is the last part if it exists and is not a last name
            suffix = name_parts[-1] if len(name_parts) > 2 else ''
            results.append(suffix)

    # Return results
    return {'result': results if extract_multiple else results[0]}

