    # Validate input
    if not isinstance(input, list) or len(input) < 2 or not all(isinstance(s, str) for s in input):
        return {'error': 'Invalid input: must be a list of at least two strings.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format: must be one of integer, text, or detailed.'}

    # Initialize total length
    total_length = 0
    lengths = []

    # Process each string
    for s in input:
        # Handle case sensitivity
        if not case_sensitive:
            s = s.lower()

        # Handle whitespace
        if ignore_whitespace:
            s = ''.join(s.split())

        # Handle ignore characters
        if ignore_characters:
            for char in ignore_characters:
                s = s.replace(char, '')

        # Handle ignore position
        if ignore_position:
            if 'first' in ignore_position and len(s) > 0:
                s = s[1:]
            if 'last' in ignore_position and len(s) > 0:
                s = s[:-1]

        # Calculate length
        length = len(s)
        lengths.append(length)
        total_length += length

    # Prepare output
    if output_format == 'integer':
        result = total_length
    elif output_format == 'text':
        result = f'The combined length is {total_length}.'
    elif output_format == 'detailed':
        result = {'total_length': total_length, 'individual_lengths': lengths}

    # Add summary statistics if requested
    if summary_statistics:
        import statistics
        avg_length = statistics.mean(lengths)
        std_dev = statistics.stdev(lengths) if len(lengths) > 1 else 0
        if isinstance(result, dict):
            result.update({'average_length': avg_length, 'standard_deviation': std_dev})
        else:
            result += f' Average length: {avg_length}, Standard deviation: {std_dev}.'

    return result

