            return {'error': 'release_date_range must contain exactly two dates.'}
        try:
            start_date, end_date = release_date_range
            # Assuming date format validation is required
            from datetime import datetime
            datetime.strptime(start_date, '%Y-%m-%d')
            datetime.strptime(end_date, '%Y-%m-%d')
        except ValueError:
            return {'error': 'Dates in release_date_range must be in YYYY-MM-DD format.'}

