# print(game_release_date_finder_v2('WWE 2K18'))", "def date_time_digit_sum(date_input, date_format='YYYY-MM-DD', delimiter='-', output_format='integer', include_time=False, sum_type='full', error_handling='raise'):
    import datetime

    def sum_digits(s):
        return sum(int(char) for char in s if char.isdigit())

    try:
        # Parse the date based on the provided format
        if date_format == 'YYYY-MM-DD':
            date_obj = datetime.datetime.strptime(date_input, '%Y-%m-%d')
        elif date_format == 'MM/DD/YYYY':
            date_obj = datetime.datetime.strptime(date_input, '%m/%d/%Y')
        else:
            raise ValueError('Unsupported date format')

        # Extract components based on sum_type
        if sum_type == 'full':
            components = [date_obj.year, date_obj.month, date_obj.day]
        elif sum_type == 'year':
            components = [date_obj.year]
        elif sum_type == 'month':
            components = [date_obj.month]
        elif sum_type == 'day':
            components = [date_obj.day]
        elif sum_type == 'time' and include_time:
            components = [date_obj.hour, date_obj.minute, date_obj.second]
        else:
            components = []

        # Calculate the sum of digits
        digit_sum = sum(sum_digits(str(component)) for component in components)

        # Return the result in the specified output format
        if output_format == 'integer':
            return digit_sum
        elif output_format == 'text':
            return f'The sum of digits is {digit_sum}'
        else:
            raise ValueError('Unsupported output format')
    except Exception as e:
        if error_handling == 'raise':
            raise e
        elif error_handling == 'ignore':
            return None

# Example usage based on the question
