print(result)", "def reverse_order(input: str, output_format: str = 'string', reverse_scope: str = 'full', partial_indices: list = None):
    # Validate input parameter
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Validate output_format parameter
    if output_format not in ['string', 'number', 'json', 'array']:
        return {'error': 'Invalid output format specified.'}

    # Validate reverse_scope parameter
    if reverse_scope not in ['full', 'partial']:
        return {'error': 'Invalid reverse scope specified.'}

    # Handle partial reversal
    if reverse_scope == 'partial':
        if not partial_indices or len(partial_indices) != 2:
            return {'error': 'Partial indices must be a list of two integers.'}
        start, end = partial_indices
        if not (0 <= start < end <= len(input)):
            return {'error': 'Invalid partial indices range.'}
        # Reverse the specified section
        reversed_section = input[start:end][::-1]
        result = input[:start] + reversed_section + input[end:]
    else:
        # Reverse the entire input
        result = input[::-1]

    # Convert result to the specified output format
    if output_format == 'number':
        try:
            result = int(result)
        except ValueError:
            return {'error': 'Reversed result cannot be converted to a number.'}
    elif output_format == 'json':
        result = {'reversed': result}
    elif output_format == 'array':
        result = list(result)

    return result

# Example usage based on the question and answer
# Reverse the order of 1945
print(reverse_order('1945', output_format='number'))  # Expected output: 5491", "def advanced_arithmetic_calculator(operation, operands, output_format='number', precision=2, error_handling='strict'):
    """
    Perform arithmetic operations based on the specified parameters.
    """
    try:
        if operation == 'add':
            result = sum(operands)
        elif operation == 'subtract':
            result = operands[0] - sum(operands[1:])
        elif operation == 'multiply':
            result = 1
            for num in operands:
                result *= num
        elif operation == 'divide':
            result = operands[0]
            for num in operands[1:]:
                if num == 0:
                    if error_handling == 'strict':
                        raise ValueError('Division by zero encountered.')
                    elif error_handling == 'warn':
                        print('Warning: Division by zero encountered. Skipping operation.')
                        return None
                    else:  # ignore
                        return None
                result /= num
        elif operation == 'modulus':
            result = operands[0]
            for num in operands[1:]:
                result %= num
        elif operation == 'exponentiate':
            result = operands[0]
            for num in operands[1:]:
                result **= num
        elif operation == 'root':
            degree = operands[0]
            if degree == 0:
                if error_handling == 'strict':
                    raise ValueError('Root degree cannot be zero.')
                elif error_handling == 'warn':
                    print('Warning: Root degree cannot be zero. Skipping operation.')
                    return None
                else:  # ignore
                    return None
            result = operands[1] ** (1 / degree)
        else:
            raise ValueError('Invalid operation specified.')

        if output_format == 'detailed':
            return f'The result of {operation} operation on {operands} is {round(result, precision)}'
        elif output_format == 'text':
            return str(round(result, precision))
        else:  # number
            return round(result, precision)

    except Exception as e:
        if error_handling == 'strict':
            raise e
        elif error_handling == 'warn':
            print(f'Warning: {str(e)}')
            return None
        else:  # ignore
            return None

# Example usage based on the question
