    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'ignore_characters must be a list of strings.'}
    if not isinstance(min_repetition, int) or min_repetition < 1:
        return {'error': 'min_repetition must be a positive integer.'}
    if not isinstance(exclude_groups, list) or not all(group in ['vowels', 'consonants'] for group in exclude_groups):
        return {'error': 'exclude_groups must be a list containing "vowels" or "consonants".'}
    if not isinstance(detailed_output, bool):
        return {'error': 'detailed_output must be a boolean.'}

    # Define vowels and consonants
    vowels = set('aeiouAEIOU')
    consonants = set('bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ')

    # Adjust input based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Filter out ignored characters
    filtered_input = ''.join(char for char in input if char not in ignore_characters)

    # Exclude groups
    if 'vowels' in exclude_groups:
        filtered_input = ''.join(char for char in filtered_input if char not in vowels)
    if 'consonants' in exclude_groups:
        filtered_input = ''.join(char for char in filtered_input if char not in consonants)

    # Count repetitions
    from collections import Counter
    letter_counts = Counter(filtered_input)

    # Filter based on min_repetition
    repeated_letters = {char: count for char, count in letter_counts.items() if count >= min_repetition}

    # Prepare output
    if detailed_output:
        return {'repeated_letters': repeated_letters}
    else:
        return {'count': len(repeated_letters)}

