    # Validate input parameters
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Invalid characters: characters must be a list of single-character strings.'}
    if output_format not in ['integer', 'text', 'json', 'csv']:
        return {'error': 'Invalid output_format: must be one of integer, text, json, csv.'}

    # Initialize count
    total_count = 0
    results = []

    # Count occurrences
    for string in input:
        count = 0
        for char in characters:
            if not case_sensitive:
                count += string.lower().count(char.lower())
            else:
                count += string.count(char)
        results.append(count)
        total_count += count

    # Determine output
    if aggregate_results:
        result = total_count
    else:
        result = results

    # Format output
    if output_format == 'integer':
        return result
    elif output_format == 'text':
        return f'Total occurrences: {result}'
    elif output_format == 'json':
        return {'total_occurrences': result}
    elif output_format == 'csv':
        return ','.join(map(str, result)) if isinstance(result, list) else str(result)

