["def publication_publisher_lookup(publication_name: str, include_historical: bool = False, multiple_publishers_handling: str = 'first', date_range: dict = None, publisher_type: str = 'all') -> str:
    """
    Find and analyze the publisher(s) of a given publication.

    Parameters:
    - publication_name (str): The name of the publication whose publisher is to be found.
    - include_historical (bool): Whether to include historical publishers. Defaults to False.
    - multiple_publishers_handling (str): How to handle multiple publishers. Defaults to 'first'.
    - date_range (dict): Optional date range to filter publishers.
    - publisher_type (str): Type of publisher to retrieve. Defaults to 'all'.

    Returns:
    - str: The publisher(s) based on the input criteria.
    """
    # Error handling for required parameter
    if not publication_name:
        return 'Error: publication_name is required.'

    # Simulated database of publications and publishers
    publication_data = {
        'Eye To The Telescope': {
            'publishers': ['Science Fiction Poetry Association'],
            'historical_publishers': []
        }
    }

    # Check if publication exists in the database
    if publication_name not in publication_data:
        return 'Error: Publication not found.'

    # Retrieve publisher information
    publishers_info = publication_data[publication_name]
    publishers = publishers_info['publishers']

    # Include historical publishers if requested
    if include_historical:
        publishers.extend(publishers_info['historical_publishers'])

    # Handle multiple publishers
    if multiple_publishers_handling == 'first':
        result = publishers[0] if publishers else 'No publishers found.'
    elif multiple_publishers_handling == 'last':
        result = publishers[-1] if publishers else 'No publishers found.'
    elif multiple_publishers_handling == 'all':
        result = ', '.join(publishers) if publishers else 'No publishers found.'
    else:
        return 'Error: Invalid value for multiple_publishers_handling.'

    # Return the result
    return result

