["def film_query_tool(director, theme, release_year=None, language=None, rating=None, output_format='title'):
    """
    Query films based on director, theme, release year, language, and rating.

    :param director: List of director names to filter films.
    :param theme: List of thematic elements to filter films.
    :param release_year: Release year of the films to be queried (optional).
    :param language: Language of the films to be queried (optional).
    :param rating: Minimum rating of the films to be queried (optional).
    :param output_format: Format of the output ('title', 'full_details', 'summary').
    :return: List of films matching the criteria in the specified format.
    """
    # Error handling for required parameters
    if not director or not theme:
        return {'error': 'Both director and theme parameters are required.'}

    # Simulated database of films
    films = [
        {'title': 'The Prestige', 'director': 'Christopher Nolan', 'theme': ['magic', 'drama'], 'release_year': 2006, 'language': 'English', 'rating': 8.5},
        # Additional film entries can be added here
    ]

    # Filter films based on provided criteria
    filtered_films = []
    for film in films:
        if (set(director).intersection([film['director']]) and
            set(theme).intersection(film['theme']) and
            (release_year is None or film['release_year'] == release_year) and
            (language is None or film['language'] == language) and
            (rating is None or film['rating'] >= rating)):
