# print(result)  # Expected output: 2006", "def reverse_number_advanced(number, output_format='string', reverse_range=None, reverse_multiple=False):
    """
    Reverses the digits of the given number(s) based on the specified parameters.

    :param number: The number(s) to be reversed. Can be a single integer, a floating-point number, or an array of such numbers.
    :param output_format: The format of the output. Defaults to 'string'.
    :param reverse_range: A dictionary specifying the 'start' and 'end' indices for the range to reverse.
    :param reverse_multiple: If true, reverses the digits of each number in an array individually.
    :return: The reversed number(s) in the specified format.
    """
    def reverse_digits(num_str, start, end):
        # Reverse the specified range of digits
        return num_str[:start] + num_str[start:end][::-1] + num_str[end:]

    def process_number(num):
        # Convert number to string to handle digit manipulation
        num_str = str(num)
        if reverse_range:
            start = reverse_range.get('start', 0)
            end = reverse_range.get('end', len(num_str))
            if start < 0 or end > len(num_str) or start >= end:
                raise ValueError("Invalid reverse range specified.")
            reversed_str = reverse_digits(num_str, start, end)
        else:
            reversed_str = num_str[::-1]

        if output_format == 'number':
            return float(reversed_str) if '.' in reversed_str else int(reversed_str)
        elif output_format == 'array':
            return list(reversed_str)
        else:
            return reversed_str

    if isinstance(number, list):
        if reverse_multiple:
            return [process_number(num) for num in number]
        else:
            combined_str = ''.join(map(str, number))
            return process_number(combined_str)
    else:
        return process_number(number)

