    # Error handling for required parameters
    if not isinstance(strings, list) or len(strings) < 2:
        return {'error': 'The strings parameter must be a list with at least two strings.'}

    # Handle null values based on the handle_null parameter
    if handle_null not in ['ignore', 'empty_string', 'error']:
        return {'error': 'Invalid handle_null option.'}

    if handle_null == 'error' and any(s is None for s in strings):
        return {'error': 'Null values are not allowed in the strings array.'}

    # Prepare strings based on parameters
    processed_strings = []
    for s in strings:
        if s is None:
            if handle_null == 'empty_string':
                s = ''
            elif handle_null == 'ignore':
                continue

        if trim_whitespace and isinstance(s, str):
            s = s.strip()

        if ignore_empty and s == '':
            continue

        if case_transformation == 'lower':
            s = s.lower()
        elif case_transformation == 'upper':
            s = s.upper()
        elif case_transformation == 'capitalize':
            s = s.capitalize()

        processed_strings.append(s)

    # Concatenate strings with the specified separator
    result = separator.join(processed_strings)
    return {'result': result}

