# print(result)  # Output: 1474"]

["def song_composer_finder(song_title: str, match_type: str = 'exact', additional_info: bool = False, language: str = None, release_year: int = None, genre: str = None, info_format: str = None):
    """
    Find the composer of a given song with enhanced search capabilities.

    Parameters:
    - song_title (str): The title of the song for which the composer is to be found.
    - match_type (str): The type of match to use when searching for the song title. Defaults to 'exact'.
    - additional_info (bool): Whether to return additional information about the composer. Defaults to False.
    - language (str): The language of the song.
    - release_year (int): The year the song was released.
    - genre (str): The genre of the song.
    - info_format (str): The format of additional information to return about the composer.

    Returns:
    - dict: A dictionary containing the composer's name and optionally additional information.
    """
    # Simulated database of songs and composers
    song_database = {
        'Oomana Thinkal': {'composer': 'M. B. Sreenivasan', 'language': 'Malayalam', 'release_year': 1980, 'genre': 'Classical'},
        # Additional songs can be added here
    }

    # Validate match_type
    if match_type not in ['exact', 'partial']:
        return {'error': 'Invalid match_type. Must be either "exact" or "partial".'}

    # Validate info_format
    if info_format and info_format not in ['biography', 'discography', 'awards']:
        return {'error': 'Invalid info_format. Must be one of "biography", "discography", or "awards".'}

    # Search for the song
    composer_info = None
    if match_type == 'exact':
        composer_info = song_database.get(song_title)
    elif match_type == 'partial':
        for title, info in song_database.items():
            if song_title.lower() in title.lower():
                composer_info = info
                break

    # If song not found
    if not composer_info:
        return {'error': 'Song not found.'}

    # Prepare the response
    response = {'composer': composer_info['composer']}

    # Add additional information if requested
    if additional_info:
        if info_format == 'biography':
            response['biography'] = 'Biography of ' + composer_info['composer']
        elif info_format == 'discography':
            response['discography'] = 'Discography of ' + composer_info['composer']
        elif info_format == 'awards':
            response['awards'] = 'Awards of ' + composer_info['composer']

    return response

# Example usage
