["def operation_director_lookup(operation_name, dataset, case_sensitive=False, include_metadata=True, filter_by_status=None):
    # Validate input types
    if not isinstance(operation_name, str):
        return {'error': 'Invalid type for operation_name, expected string.'}
    if not isinstance(dataset, list):
        return {'error': 'Invalid type for dataset, expected list.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid type for case_sensitive, expected boolean.'}
    if not isinstance(include_metadata, bool):
        return {'error': 'Invalid type for include_metadata, expected boolean.'}
    if filter_by_status and filter_by_status not in ['ongoing', 'completed', 'planned']:
        return {'error': 'Invalid value for filter_by_status, expected one of ongoing, completed, planned.'}

    # Prepare the search term
    search_term = operation_name if case_sensitive else operation_name.lower()

    # Search for the operation
    for entry in dataset:
        # Validate entry structure
        if 'operation' not in entry or 'director' not in entry:
            continue

        # Apply case sensitivity
        operation = entry['operation'] if case_sensitive else entry['operation'].lower()

        # Check if operation matches and apply status filter if provided
        if search_term in operation and (not filter_by_status or entry.get('status') == filter_by_status):
            # Prepare the result
            result = {'director': entry['director']}
            if include_metadata:
                result.update({
                    'operation': entry['operation'],
                    'start_date': entry.get('start_date'),
                    'end_date': entry.get('end_date'),
                    'status': entry.get('status'),
                    'department': entry.get('department')
                })
            return result

    # If no match is found
    return {'error': 'No matching operation found.'}

