    # Error handling for input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'ignore_characters must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last', 'even', 'odd'] for pos in ignore_position):
        return {'error': 'ignore_position must be a list containing any of ["first", "last", "even", "odd"].'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if not isinstance(ignore_whitespace, bool):
        return {'error': 'ignore_whitespace must be a boolean.'}
    if not isinstance(ignore_special_characters, bool):
        return {'error': 'ignore_special_characters must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'output_format must be one of ["integer", "text", "detailed"].'}

    # Prepare the input string based on parameters
    if not case_sensitive:
        input = input.lower()
    if ignore_whitespace:
        input = ''.join(input.split())
    if ignore_special_characters:
        input = ''.join(filter(str.isalnum, input))

    # Remove ignored characters
    for char in ignore_characters:
        input = input.replace(char, '')

    # Remove characters based on ignored positions
    if 'first' in ignore_position and len(input) > 0:
        input = input[1:]
    if 'last' in ignore_position and len(input) > 0:
        input = input[:-1]
    if 'even' in ignore_position:
        input = ''.join([char for idx, char in enumerate(input) if idx % 2 != 0])
    if 'odd' in ignore_position:
        input = ''.join([char for idx, char in enumerate(input) if idx % 2 == 0])

    # Count the letters
    letter_count = sum(char.isalpha() for char in input)

    # Return the result based on the output format
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The number of letters is {letter_count}.'
    elif output_format == 'detailed':
        return {
            'total_letters': letter_count,
            'details': {
                'lowercase': sum(char.islower() for char in input),
                'uppercase': sum(char.isupper() for char in input)
            }
        }

