    """
    Find the closest palindrome year to the given input year.

    Parameters:
    - year (int): The input year for which the closest palindrome year is to be found.
    - direction (str): The direction to search for the palindrome year. Defaults to 'both'.
    - output_format (str): The format of the output. Defaults to 'integer'.
    - range_limit (int): The maximum number of years to search in each direction. Defaults to no limit.
    - return_all (bool): If true, returns all palindrome years within the specified range. Defaults to false.

    Returns:
    - int or str: The closest palindrome year or a list of palindrome years based on the parameters.
    """
    def is_palindrome(y):
        return str(y) == str(y)[::-1]

    if not isinstance(year, int):
        raise ValueError("Year must be an integer.")
    if direction not in ['both', 'past', 'future']:
        raise ValueError("Direction must be 'both', 'past', or 'future'.")
    if output_format not in ['integer', 'text']:
        raise ValueError("Output format must be 'integer' or 'text'.")

    closest_years = []
    search_range = range_limit if range_limit is not None else float('inf')

    def search(year, step):
        count = 0
        while count < search_range:
            year += step
            if is_palindrome(year):
                closest_years.append(year)
                break
            count += 1

    if direction in ['both', 'past']:
        search(year, -1)
    if direction in ['both', 'future']:
        search(year, 1)

    if not closest_years:
        return None

    closest_years.sort(key=lambda y: abs(y - year))
    result = closest_years if return_all else closest_years[0]

    if output_format == 'text':
        return str(result)
    return result

