# Output: '1 October 1895'", "def date_calculator(start_date, duration, operation, output_format='YYYY-MM-DD', time_zone=None, business_days_only=False):
    from datetime import datetime, timedelta
    import pytz

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Validate operation
    if operation not in ['add', 'subtract']:
        return {'error': 'Invalid operation. Must be "add" or "subtract".'}

    # Validate duration
    value = duration.get('value')
    unit = duration.get('unit')
    if not isinstance(value, int) or unit not in ['days', 'weeks', 'months', 'years']:
        return {'error': 'Invalid duration. Ensure value is an integer and unit is one of ["days", "weeks", "months", "years"].'}

    # Calculate the new date
    if unit == 'days':
        delta = timedelta(days=value)
    elif unit == 'weeks':
        delta = timedelta(weeks=value)
    elif unit == 'months':
        # Approximate month handling
        month = start_date_obj.month - 1 + value
        year = start_date_obj.year + month // 12
        month = month % 12 + 1
        day = min(start_date_obj.day, [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month-1])
        new_date = datetime(year, month, day)
        delta = new_date - start_date_obj
    elif unit == 'years':
        try:
            new_date = start_date_obj.replace(year=start_date_obj.year + value)
            delta = new_date - start_date_obj
        except ValueError:
            return {'error': 'Invalid date resulting from year addition/subtraction.'}

    if operation == 'subtract':
        delta = -delta

    result_date = start_date_obj + delta

    # Handle time zone
    if time_zone:
        try:
            tz = pytz.timezone(time_zone)
            result_date = tz.localize(result_date)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Unknown time zone specified.'}

    # Handle business days only
    if business_days_only:
        while result_date.weekday() >= 5:  # 5 = Saturday, 6 = Sunday
            result_date += timedelta(days=1 if operation == 'add' else -1)

    # Format the output
    if output_format == 'YYYY-MM-DD':
        formatted_date = result_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = result_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = result_date.strftime('%d-%m-%Y')
    elif output_format == 'ISO8601':
        formatted_date = result_date.isoformat()
    else:
        return {'error': 'Invalid output format specified.'}

    return {'result': formatted_date}

# Example usage based on the question
result = date_calculator(start_date='1895-10-01', duration={'value': 1, 'unit': 'weeks'}, operation='subtract')
