    """
    # Error handling for non-numeric inputs
    if not isinstance(number1, (int, float)) or not isinstance(number2, (int, float)):
        if error_handling == 'ignore':
            return None
        elif error_handling == 'warn':
            print('Warning: Non-numeric input encountered.')
            return None
        elif error_handling == 'strict':
            raise ValueError('Non-numeric input encountered.')

    # Calculate the difference
    difference = number1 - number2

    # Handle negative results if specified
    if handle_negative and difference < 0:
        difference = abs(difference)

    # Format the output based on the specified format
    if output_format == 'integer':
        return int(difference)
    elif output_format == 'float':
        return round(float(difference), precision)
    elif output_format == 'text':
        return str(difference)
    elif output_format == 'scientific':
        return f'{difference:.{precision}e}'
    else:
        # Default behavior if output_format is not recognized
        return difference

