        return {'error': 'event_filter must be a string.'}", "def extract_last_name(full_name, delimiter=' ', case_sensitive=True, exclude_words=[], multi_word_last_name=False, cultural_variation='western'):
    """
    Extracts the last name from a full name string based on specified parameters.
    """
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Error handling for optional parameters
    if not isinstance(delimiter, str):
        return {'error': 'Invalid delimiter. It must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive. It must be a boolean.'}
    if not isinstance(exclude_words, list) or not all(isinstance(word, str) for word in exclude_words):
        return {'error': 'Invalid exclude_words. It must be a list of strings.'}
    if not isinstance(multi_word_last_name, bool):
        return {'error': 'Invalid multi_word_last_name. It must be a boolean.'}
    if cultural_variation not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid cultural_variation. It must be one of ["western", "eastern", "custom"].'}

    # Normalize the full name based on case sensitivity
    if not case_sensitive:
        full_name = full_name.lower()
        exclude_words = [word.lower() for word in exclude_words]

    # Split the full name into parts
    name_parts = full_name.split(delimiter)

    # Filter out excluded words
    name_parts = [part for part in name_parts if part not in exclude_words]

    # Extract the last name based on cultural variation
    if cultural_variation == 'western':
        # Western convention: last part is typically the last name
        last_name = name_parts[-1] if name_parts else ''
    elif cultural_variation == 'eastern':
        # Eastern convention: first part is typically the last name
        last_name = name_parts[0] if name_parts else ''
    else:
        # Custom logic can be added here
        last_name = name_parts[-1] if name_parts else ''

    # Handle multi-word last names
    if multi_word_last_name and len(name_parts) > 1:
        last_name = ' '.join(name_parts[-2:])

    return {'last_name': last_name}

