# print(last_name)  # Output: Enyedi", "def extract_last_character(input: str, ignore_characters: list = [], ignore_position: list = [], case_sensitive: bool = True, ignore_whitespace: bool = False, sequence_length: int = 1):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'ignore_characters must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(isinstance(p, int) for p in ignore_position):
        return {'error': 'ignore_position must be a list of integers.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if not isinstance(ignore_whitespace, bool):
        return {'error': 'ignore_whitespace must be a boolean.'}
    if not isinstance(sequence_length, int) or sequence_length < 1:
        return {'error': 'sequence_length must be a positive integer.'}

    # Adjust input based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [c.lower() for c in ignore_characters]

    # Filter out ignored characters and positions
    filtered_input = []
    for i, char in enumerate(input):
        if (char in ignore_characters or (ignore_whitespace and char.isspace()) or i in ignore_position):
            continue
        filtered_input.append(char)

    # Extract the last sequence_length characters
    if len(filtered_input) < sequence_length:
        return {'error': 'Not enough characters to extract the desired sequence length.'}

    result = ''.join(filtered_input[-sequence_length:])
    return {'result': result}

