            full_name = full_name.replace('Mr. ', '').replace('Ms. ', '')
        if ignore_suffixes:
            full_name = full_name.replace(' Jr.', '').replace(' Sr.', '')

        # Split the name into components
        name_parts = full_name.split()
        if name_order == 'last_first_middle':
            name_parts = name_parts[-1:] + name_parts[:-1]

        # Extract components based on the order
        first_name = name_parts[0] if name_parts else ''
        middle_name = name_parts[1] if len(name_parts) > 2 else ''
        last_name = name_parts[-1] if len(name_parts) > 1 else ''

        if not extract_middle_name:
