        if output_case == 'uppercase':
            s = s.upper()
        elif output_case == 'lowercase':
            s = s.lower()
        elif output_case == 'capitalize':
            s = s.capitalize()

        return s

    # Process each string in the input list
    result = [reverse_string(s) for s in input]

