    """
    Extracts the last name from a full name string based on the specified parameters.

    :param full_name: The full name from which to extract the last name.
    :param name_format: The expected format of the name.
    :param ignore_suffix: Whether to ignore suffixes like Jr., Sr., etc.
    :param include_middle_name: Whether to include the middle name in the extraction.
    :param suffix_handling: Determines how suffixes are handled.
    :return: The extracted last name.
    """
    # Error handling for empty full_name
    if not full_name.strip():
        return "Error: 'full_name' must be a non-empty string."

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle different name formats
    if name_format == 'standard':
        # Standard format assumes the last word is the last name
        last_name = name_parts[-1]
    elif name_format == 'hyphenated':
        # Hyphenated format may have hyphenated last names
        last_name = name_parts[-1]
        if '-' in last_name:
            last_name = last_name.split('-')[-1]
    elif name_format == 'multiple_last_names':
        # Multiple last names format assumes the last two words are the last name
        last_name = ' '.join(name_parts[-2:])
    elif name_format == 'international':
        # International format may vary; assume last word is last name for simplicity
        last_name = name_parts[-1]
    else:
        return "Error: Invalid 'name_format' specified."

    # Handle suffixes based on suffix_handling
    if suffix_handling == 'ignore' and ignore_suffix:
        # Remove common suffixes if present
        suffixes = ['Jr.', 'Sr.', 'III', 'IV']
        if last_name in suffixes:
            last_name = name_parts[-2] if len(name_parts) > 1 else last_name
    elif suffix_handling == 'include':
        # Include suffix in the last name
        pass  # Already included by default
    elif suffix_handling == 'separate':
        # Separate suffix from last name
        suffixes = ['Jr.', 'Sr.', 'III', 'IV']
        if last_name in suffixes:
            last_name = name_parts[-2] if len(name_parts) > 1 else last_name
    else:
        return "Error: Invalid 'suffix_handling' specified."

    # Include middle name if specified
    if include_middle_name and len(name_parts) > 2:
        middle_name = ' '.join(name_parts[1:-1])
        last_name = f"{middle_name} {last_name}"

    return last_name

# Example usage based on the question
