    # Error handling for required 'input' parameter
    if not isinstance(input, str) or not input:
        return {'error': 'Input must be a non-empty string.'}

    # Determine the set of characters to consider based on 'character_set'
    if character_set == 'alphabetic':
        characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
    elif character_set == 'alphanumeric':
        characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    elif character_set == 'custom':
        characters = custom_characters
    else:
        return {'error': 'Invalid character_set value.'}

    # Filter input based on 'ignore_non_alphabetic' and 'case_sensitive'
    if ignore_non_alphabetic:
        input = ''.join(filter(str.isalpha, input))
    if not case_sensitive:
        input = input.lower()
        characters = characters.lower()

    # Count the characters
    count = sum(1 for char in input if char in characters)

    # Prepare the output
    if output_format == 'integer':
        result = count
    elif output_format == 'text':
        result = f'The count is {count}.'
    else:
        return {'error': 'Invalid output_format value.'}

    # Add verbosity if required
    if output_verbosity == 'detailed':
        result = {
            'count': count,
            'input_length': len(input),
            'original_input': input
        }

    return result

