print(extract_first_name('Sun Jian'))  # Expected output: 'Sun'", "def letter_counter(input, ignore_non_letters=False, case_sensitive=False, output_format='integer', include_spaces=False):
    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 20:
        return {'error': 'Input must be a list of 1 to 20 strings.'}
    if not all(isinstance(item, str) for item in input):
        return {'error': 'All items in the input list must be strings.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format specified.'}

    # Initialize count dictionary
    letter_count = {}

    # Process each string in the input list
    for string in input:
        for char in string:
            # Handle spaces
            if char == ' ' and not include_spaces:
                continue
            # Handle non-letter characters
            if ignore_non_letters and not char.isalpha():
                continue
            # Handle case sensitivity
            if not case_sensitive:
                char = char.lower()
            # Count the character
            if char in letter_count:
                letter_count[char] += 1
            else:
                letter_count[char] = 1

    # Format output
    if output_format == 'integer':
        return sum(letter_count.values())
    elif output_format == 'text':
        return ' '.join([f'{char}:{count}' for char, count in letter_count.items()])
    elif output_format == 'detailed':
        return letter_count

