    """
    Extracts the last name from a full name string based on the specified parameters.
    """
    # Default prefix and suffix lists
    default_prefixes = ['Dr.', 'Mr.', 'Mrs.', 'Ms.']
    default_suffixes = ['Jr.', 'Sr.', 'III']

    # Use custom lists if provided
    prefixes = prefix_list if prefix_list is not None else default_prefixes
    suffixes = suffix_list if suffix_list is not None else default_suffixes

    # Error handling for required parameter
    if not full_name:
        raise ValueError("The 'full_name' parameter is required.")

    # Split the full name based on the name format
    if name_format == 'western':
        name_parts = full_name.split()
    elif name_format == 'eastern':
        name_parts = full_name.split()
        name_parts.reverse()  # Eastern format typically has the last name first
    elif name_format == 'custom' and custom_delimiter:
        name_parts = full_name.split(custom_delimiter)
    elif name_format == 'compound':
        name_parts = full_name.split()
    else:
        raise ValueError("Invalid 'name_format' value.")

    # Remove prefixes if needed
    if ignore_prefixes:
        name_parts = [part for part in name_parts if part not in prefixes]

    # Handle suffixes
    if recognize_suffixes and name_parts[-1] in suffixes:
        name_parts.pop()

    # Extract the last name
    if name_format == 'western' or name_format == 'compound':
        last_name = name_parts[-1]
    elif name_format == 'eastern':
        last_name = name_parts[0]
    else:
        last_name = name_parts[-1]

    # Include middle name if required
    if include_middle_name and len(name_parts) > 2:
        last_name = ' '.join(name_parts[1:])

    return last_name

