    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if not isinstance(include_special_characters, bool):
        return {'error': 'include_special_characters must be a boolean.'}
    if not isinstance(include_digits, bool):
        return {'error': 'include_digits must be a boolean.'}
    if not isinstance(include_whitespace, bool):
        return {'error': 'include_whitespace must be a boolean.'}
    if output_detail not in ['summary', 'detailed']:
        return {'error': "output_detail must be 'summary' or 'detailed'."}
    if character_subset is not None and not all(isinstance(c, str) and len(c) == 1 for c in character_subset):
        return {'error': 'character_subset must be a list of single-character strings.'}

    # Normalize input based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Filter characters based on inclusion settings
    filtered_input = ''
    for char in input:
        if char.isalpha() or (include_digits and char.isdigit()) or (include_special_characters and not char.isalnum()) or (include_whitespace and char.isspace()):
            if character_subset is None or char in character_subset:
                filtered_input += char

    # Count repeated characters
    from collections import Counter
    char_count = Counter(filtered_input)
    repeated_count = {char: count for char, count in char_count.items() if count > 1}

    # Prepare output
    if output_detail == 'summary':
        return {'repeated_count': sum(repeated_count.values())}
    else:
        return {'repeated_count': repeated_count}

# Example usage for the question
