    """
    Find the closest palindrome year(s) to the given year.

    Parameters:
    - year (int): The year for which the closest palindrome number is to be found.
    - search_range (int, optional): The range of years to search for palindrome numbers. Defaults to 100.
    - output_format (str, optional): The format of the output. Defaults to 'integer'.
    - include_input_year (bool, optional): Whether to include the input year in the search. Defaults to False.
    - number_of_results (int, optional): The number of closest palindrome years to return. Defaults to 1.

    Returns:
    - The closest palindrome year(s) based on the specified output format.
    """
    def is_palindrome(y):
        return str(y) == str(y)[::-1]

    if not isinstance(year, int) or not isinstance(search_range, int) or not isinstance(number_of_results, int):
        return {'error': 'Invalid input type. Year, search_range, and number_of_results must be integers.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of: integer, text, detailed.'}

    palindromes = []
    for i in range(year - search_range, year + search_range + 1):
        if i == year and not include_input_year:
            continue
        if is_palindrome(i):
            palindromes.append(i)

    palindromes.sort(key=lambda x: abs(x - year))
    closest_palindromes = palindromes[:number_of_results]

    if output_format == 'integer':
        return closest_palindromes[0] if number_of_results == 1 else closest_palindromes
    elif output_format == 'text':
        return ', '.join(map(str, closest_palindromes))
    elif output_format == 'detailed':
        return {
            'closest_palindromes': closest_palindromes,
            'distances': [abs(x - year) for x in closest_palindromes]
        }"]

