# print(response)  # Expected output: {'premiere_date': 'September 30, 2009'}", "def date_calculator(start_date, years=0, months=0, days=0, hours=0, minutes=0, seconds=0, calendar_system='Gregorian', calculate_difference=False, end_date=None):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Error handling for incorrect date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected format: YYYY-MM-DDTHH:MM:SS.'}

    # Error handling for calendar system
    if calendar_system not in ['Gregorian', 'Julian', 'Lunar']:
        return {'error': 'Invalid calendar system. Supported systems: Gregorian, Julian, Lunar.'}

    # Calculate new date by adding years, months, days, etc.
    new_date = start_date_obj + relativedelta(years=years, months=months, days=days, hours=hours, minutes=minutes, seconds=seconds)

    # Return the new date in the specified format
    return {'result': new_date.strftime('%Y-%m-%dT%H:%M:%S')}

