    # Validate inputs
    if not isinstance(inputs, list) or not all(isinstance(s, str) for s in inputs):
        return {'error': 'Invalid input: inputs must be a list of strings.'}
    if not isinstance(vowels, list) or not all(isinstance(v, str) for v in vowels):
        return {'error': 'Invalid input: vowels must be a list of strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Invalid input: ignore_characters must be a list of strings.'}
    if not isinstance(count_individual_vowels, bool):
        return {'error': 'Invalid input: count_individual_vowels must be a boolean.'}
    if not isinstance(detailed_statistics, bool):
        return {'error': 'Invalid input: detailed_statistics must be a boolean.'}

    # Prepare vowels set
    if not case_sensitive:
        vowels = [v.lower() for v in vowels]

    # Count vowels
    total_vowel_count = 0
    individual_counts = {v: 0 for v in vowels}

    for string in inputs:
        if not case_sensitive:
            string = string.lower()
        for char in string:
            if char in ignore_characters:
                continue
            if char in vowels:
                total_vowel_count += 1
                if count_individual_vowels:
                    individual_counts[char] += 1

    # Prepare result
    result = {'total_vowel_count': total_vowel_count}
    if count_individual_vowels:
        result['individual_counts'] = individual_counts
    if detailed_statistics:
        result['detailed_statistics'] = {
            'total_count': total_vowel_count,
            'individual_counts': individual_counts,
            'percentages': {v: (individual_counts[v] / total_vowel_count * 100) if total_vowel_count > 0 else 0 for v in vowels}
        }

    return result

# Example usage based on the question
