# Expected output: {'first_name': 'Meghan'}", "def count_repeated_letters(input, case_sensitive=False, output_format='integer', ignore_characters='', consecutive_only=False):
    # Validate input parameters
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = ignore_characters.lower()

    # Remove ignored characters
    filtered_input = ''.join([char for char in input if char not in ignore_characters])

    # Initialize a dictionary to count repeated letters
    letter_counts = {}

    # Count repeated letters
    for i, char in enumerate(filtered_input):
        if char.isalpha():
            if consecutive_only:
                # Check for consecutive repetition
                if i > 0 and char == filtered_input[i - 1]:
                    letter_counts[char] = letter_counts.get(char, 0) + 1
            else:
                # Count all repetitions
                if char in filtered_input[i + 1:]:
                    letter_counts[char] = letter_counts.get(char, 0) + 1

    # Format the output
    if output_format == 'integer':
        return sum(letter_counts.values())
    elif output_format == 'text':
        return f'Total repeated letters: {sum(letter_counts.values())}'
    elif output_format == 'detailed':
        return letter_counts

# Example usage based on the question
result = count_repeated_letters('Meghan')
print(result)  # Output: 0"]

