    # Error handling for required parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Convert input to lowercase if case_sensitive is False
    if not case_sensitive:
        input = input.lower()
        exclude_characters = [char.lower() for char in exclude_characters]

    # Define character sets
    if character_set == 'alphabet':
        valid_chars = set('abcdefghijklmnopqrstuvwxyz')
    elif character_set == 'numeric':
        valid_chars = set('0123456789')
    elif character_set == 'alphanumeric':
        valid_chars = set('abcdefghijklmnopqrstuvwxyz0123456789')
    else:
        return {'error': 'Invalid character set specified.'}

    # Include whitespace if specified
    if include_whitespace:
        valid_chars.add(' ')

    # Filter input based on valid characters and exclusions
    filtered_input = [char for char in input if char in valid_chars and char not in exclude_characters]

    # Count unique characters
    unique_chars = set(filtered_input)
    unique_count = len(unique_chars)

    # Prepare detailed output if required
    if detailed_output:
        detailed_counts = {char: filtered_input.count(char) for char in unique_chars}
