    - operand_type (str): Specifies whether the operands are real or complex numbers.

    Returns:
    - The result of the arithmetic operation in the specified format.
    """
    # Error handling for invalid operations
    if operation not in ['add', 'subtract', 'multiply', 'divide', 'modulus', 'exponentiation', 'root']:
        return "Error: Invalid operation."

    # Error handling for insufficient operands
    if len(operands) < 2:
        return "Error: At least two operands are required."

    # Error handling for unsupported operand types
    if operand_type not in ['real', 'complex']:
        return "Error: Unsupported operand type."

    # Perform the arithmetic operation
    result = None
    if operation == 'subtract':
        result = operands[1] - operands[0]

    # Format the result according to the output_format
    if output_format == 'integer':
        result = int(result)
    elif output_format == 'float':
        result = round(float(result), precision)
    elif output_format == 'scientific':
        result = f"{result:.{precision}e}"
    elif output_format == 'text':
        result = str(result)

    return result

