    # Validate input
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        if error_handling == 'error':
            raise ValueError('Invalid input: All items must be strings.')
        elif error_handling == 'warn':
            print('Warning: Invalid input detected. Ignoring non-string items.')
        input = [i for i in input if isinstance(i, str)]

    # Handle empty strings if required
    if handle_empty:
        input = [i if i else 'N/A' for i in input]

    # Extract first letters
    first_letters = []
    for string in input:
        if string:
            first_letter = string[0] if case_sensitivity else string[0].lower()
            first_letters.append(first_letter)
        elif handle_empty:
            first_letters.append('N/A')

    # Format output
    if output_format == 'character':
        return first_letters[0] if first_letters else ''
    elif output_format == 'text':
        return ', '.join(first_letters)
    elif output_format == 'json':
        return {'first_letters': first_letters}

