print(result)  # Expected output: 'September 25, 2017'", "def date_calculator(start_date, duration, direction, output_format='YYYY-MM-DD', validate_date=True):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Validate start_date format
    try:
        date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Validate duration unit
    if duration['unit'] not in ['days', 'weeks', 'months', 'years']:
        return {'error': 'Invalid duration unit. Expected one of: days, weeks, months, years.'}

    # Calculate new date based on direction
    if direction == 'before':
        if duration['unit'] == 'days':
            new_date = date_obj - timedelta(days=duration['value'])
        elif duration['unit'] == 'weeks':
            new_date = date_obj - timedelta(weeks=duration['value'])
        elif duration['unit'] == 'months':
            new_date = date_obj - relativedelta(months=duration['value'])
        elif duration['unit'] == 'years':
            new_date = date_obj - relativedelta(years=duration['value'])
    elif direction == 'after':
        if duration['unit'] == 'days':
            new_date = date_obj + timedelta(days=duration['value'])
        elif duration['unit'] == 'weeks':
            new_date = date_obj + timedelta(weeks=duration['value'])
        elif duration['unit'] == 'months':
            new_date = date_obj + relativedelta(months=duration['value'])
        elif duration['unit'] == 'years':
            new_date = date_obj + relativedelta(years=duration['value'])
    else:
        return {'error': 'Invalid direction. Expected before or after.'}

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = new_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date.strftime('%d-%m-%Y')
    elif output_format == 'ISO8601':
        formatted_date = new_date.isoformat()
    elif output_format == 'RFC2822':
        formatted_date = new_date.strftime('%a, %d %b %Y %H:%M:%S +0000')
    else:
        return {'error': 'Invalid output_format. Expected one of: YYYY-MM-DD, MM-DD-YYYY, DD-MM-YYYY, ISO8601, RFC2822.'}

    return {'result': formatted_date}

# Example usage:
