    """
    Extracts the first name from a full name string based on specified parameters.

    :param full_name: The full name from which the first name is to be extracted.
    :param delimiter: The character used to separate the components of the name.
    :param ignore_prefixes: Whether to ignore common prefixes such as 'Dr.', 'Mr.', 'Ms.', etc.
    :param middle_name_handling: Specifies how to handle middle names.
    :param suffix_handling: Whether to consider suffixes as part of the name.
    :param cultural_variation: Specifies the cultural naming convention to be used.
    :return: The extracted first name.
    """
    if not isinstance(full_name, str) or not full_name:
        return "Error: 'full_name' must be a non-empty string."

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handle prefixes if required
    if ignore_prefixes:
        prefixes = {'Dr.', 'Mr.', 'Ms.', 'Mrs.', 'Miss'}
        name_parts = [part for part in name_parts if part not in prefixes]

    # Handle suffixes if required
    if suffix_handling:
        suffixes = {'Jr.', 'Sr.', 'III', 'IV'}
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle middle names based on the specified option
    if middle_name_handling == 'ignore':
        first_name = name_parts[0] if name_parts else ''
    elif middle_name_handling == 'include':
        first_name = ' '.join(name_parts[:-1]) if len(name_parts) > 1 else name_parts[0]
    elif middle_name_handling == 'separate':
        first_name = name_parts[0] if name_parts else ''
    else:
        return "Error: Invalid option for 'middle_name_handling'."

    # Return the first name
    return first_name

# Example usage
first_name = extract_first_name('Kareena Kapoor')
print(first_name)  # Output: Kareena", "def vowel_counter(inputs, vowels_to_count=None, ignore_case=True, language='en', detailed_output=False):
    # Default vowels to count if not specified
    if vowels_to_count is None:
        vowels_to_count = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']

    # Validate inputs
    if not isinstance(inputs, list) or not all(isinstance(i, str) for i in inputs):
        return {'error': 'Invalid input: inputs must be a list of strings.'}
    if not isinstance(vowels_to_count, list) or not all(v in ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'] for v in vowels_to_count):
        return {'error': 'Invalid vowels_to_count: must be a list of specified vowels.'}
    if language not in ['en', 'es', 'fr', 'de']:
        return {'error': 'Unsupported language. Supported languages are en, es, fr, de.'}
    if not isinstance(ignore_case, bool) or not isinstance(detailed_output, bool):
        return {'error': 'Invalid parameter: ignore_case and detailed_output must be boolean values.'}

    # Prepare vowels set for counting
    if ignore_case:
        vowels_to_count = set(v.lower() for v in vowels_to_count)
    else:
        vowels_to_count = set(vowels_to_count)

    # Initialize count
    total_count = 0
    detailed_counts = {v: 0 for v in vowels_to_count} if detailed_output else None

    # Count vowels
    for string in inputs:
        for char in string:
            char_to_check = char.lower() if ignore_case else char
            if char_to_check in vowels_to_count:
                total_count += 1
                if detailed_output:
                    detailed_counts[char_to_check] += 1

    # Return result
    if detailed_output:
        return {'total_count': total_count, 'detailed_counts': detailed_counts}
    else:
        return {'total_count': total_count}

# Example usage based on the question:
# How many vowels are there in Kareena?
result = vowel_counter(inputs=['Kareena'])
