        return {'error': 'Invalid encoding. Must be UTF-8 or ASCII.'}

    # Convert characters to binary
    binary_values = []
    for char in characters:
        if len(char) != 1:
            return {'error': 'Each item in characters must be a single character string.'}
        binary_value = format(ord(char), 'b')
        if padding:
            binary_value = binary_value.zfill(8)
        binary_values.append(binary_value)

    # Format output
    if output_format == 'binary_string':
        return ''.join(binary_values)
    elif output_format == 'binary_list':
        return binary_values
    elif output_format == 'binary_dict':
        return {char: binary for char, binary in zip(characters, binary_values)}

