    return last_name.strip()", "def character_counter_plus(input, characters, case_sensitive=True, output_format='integer', filter={'min_count': 0, 'max_count': 1000}):
    """
    Count occurrences of specified characters in a list of strings.

    Parameters:
    - input (list of str): The strings to search.
    - characters (list of str): Characters or character sets to count.
    - case_sensitive (bool): Whether the search is case-sensitive.
    - output_format (str): Format of the output ('integer', 'text', 'detailed').
    - filter (dict): Filtering criteria for the output.

    Returns:
    - int, str, or dict: Count of characters based on the specified format.
    """
    # Error handling for input validation
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input):
        raise ValueError("Input must be a list of strings.")
    if not isinstance(characters, list) or not all(isinstance(c, str) for c in characters):
        raise ValueError("Characters must be a list of strings.")
    if not isinstance(case_sensitive, bool):
        raise ValueError("Case_sensitive must be a boolean.")
    if output_format not in ['integer', 'text', 'detailed']:
        raise ValueError("Output_format must be 'integer', 'text', or 'detailed'.")

    # Initialize count dictionary
    count_dict = {char: 0 for char in characters}

    # Define character sets
    char_sets = {
        'vowels': 'aeiouAEIOU' if case_sensitive else 'aeiou',
        # Add more predefined sets as needed
    }

    # Count occurrences
    for string in input:
        for char in characters:
            if char in char_sets:
                # Count occurrences of character set
                for c in char_sets[char]:
                    count_dict[char] += string.count(c) if case_sensitive else string.lower().count(c.lower())
            else:
                # Count occurrences of single character
                count_dict[char] += string.count(char) if case_sensitive else string.lower().count(char.lower())

    # Apply filter
    filtered_counts = {char: count for char, count in count_dict.items() if filter['min_count'] <= count <= filter['max_count']}

    # Format output
    if output_format == 'integer':
        return sum(filtered_counts.values())
    elif output_format == 'text':
        return ', '.join(f"{char}: {count}" for char, count in filtered_counts.items())
    elif output_format == 'detailed':
        return filtered_counts

# Example usage based on the question
