    """
    Calculate the sum of a list of numbers with options for output format and rounding.

    :param numbers: List of numbers to be summed.
    :param output_format: The format of the output ('integer', 'text', 'float').
    :param rounding: Dictionary with rounding options.
    :return: Sum of numbers in the specified format.
    """
    # Validate input types
    if not isinstance(numbers, list) or not all(isinstance(n, (int, float)) for n in numbers):
        return "Error: 'numbers' must be a list of numbers."
    if output_format not in ['integer', 'text', 'float']:
        return "Error: 'output_format' must be one of 'integer', 'text', 'float'."
    if not isinstance(rounding, dict) or 'enabled' not in rounding:
        return "Error: 'rounding' must be a dictionary with at least the 'enabled' key."

    # Calculate the sum
    total_sum = sum(numbers)

    # Apply rounding if enabled and output format is 'float'
    if rounding['enabled'] and output_format == 'float':
        decimals = rounding.get('decimals', 2)
        if not isinstance(decimals, int) or decimals < 0:
            return "Error: 'decimals' must be a non-negative integer."
        total_sum = round(total_sum, decimals)

    # Format the output
    if output_format == 'integer':
        return int(total_sum)
    elif output_format == 'text':
        return str(total_sum)
    elif output_format == 'float':
