# print(result)", "def extract_first_name(full_name, ignore_middle_names=True, case_sensitive=False, handle_prefixes=False, handle_suffixes=False, cultural_format='Western'):
    # Validate input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(ignore_middle_names, bool) or not isinstance(case_sensitive, bool) or not isinstance(handle_prefixes, bool) or not isinstance(handle_suffixes, bool):
        return {'error': 'Invalid input: Boolean parameters must be of type bool.'}
    if not isinstance(cultural_format, str):
        return {'error': 'Invalid input: cultural_format must be a string.'}

    # Handle case sensitivity
    if not case_sensitive:
        full_name = full_name.lower()

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle prefixes
    if handle_prefixes and name_parts[0].lower() in ['mr.', 'dr.', 'ms.', 'mrs.']:
        name_parts = name_parts[1:]

    # Handle suffixes
    if handle_suffixes and name_parts[-1].lower() in ['jr.', 'sr.', 'iii', 'iv']:
        name_parts = name_parts[:-1]

    # Extract first name based on cultural format
    if cultural_format.lower() == 'western':
        first_name = name_parts[0]
    else:
        # For simplicity, assume non-Western formats use the last part as the first name
        first_name = name_parts[-1]

    # Return the first name, considering middle names if specified
    if ignore_middle_names:
        return {'first_name': first_name.capitalize()}
    else:
        return {'first_name': ' '.join([part.capitalize() for part in name_parts])}

