        {'title': 'Superstore', 'actor_name': 'Johnny Pemberton', 'character_name': 'Bo Thompson', 'network': 'NBC', 'genre': 'Sitcom', 'release_year': 2015, 'episode_count': 113, 'language': 'English', 'popularity': 8.0},
        # Additional TV shows can be added here
    ]

