    # Default consonants if custom_consonants is not provided
    if custom_consonants is None:
        custom_consonants = ['b', 'c', 'd', 'f', 'g', 'h', 'j', 'k', 'l', 'm', 'n', 'p', 'q', 'r', 's', 't', 'v', 'w', 'x', 'y', 'z']

    # Default exclude_characters if not provided
    if exclude_characters is None:
        exclude_characters = []

    # Default advanced_filtering if not provided
    if advanced_filtering is None:
        advanced_filtering = {'min_occurrences': 1, 'max_occurrences': None}

    # Convert input to lowercase if case_sensitive is False
    if not case_sensitive:
        input = input.lower()
        custom_consonants = [c.lower() for c in custom_consonants]
        exclude_characters = [c.lower() for c in exclude_characters]

    # Count consonants
    consonant_count = {}
    for char in input:
        if char in custom_consonants and char not in exclude_characters:
            if char in consonant_count:
                consonant_count[char] += 1
            else:
                consonant_count[char] = 1

    # Apply advanced filtering
    min_occurrences = advanced_filtering.get('min_occurrences', 1)
    max_occurrences = advanced_filtering.get('max_occurrences', None)

    total_consonants = 0
    for char, count in consonant_count.items():
        if count >= min_occurrences and (max_occurrences is None or count <= max_occurrences):
