    # Validate input
    if not isinstance(strings, list) or len(strings) < 2:
        raise ValueError("'strings' must be a list with at least two strings.")
    if order and (not isinstance(order, list) or any(i >= len(strings) or i < 0 for i in order)):
        raise ValueError("'order' must be a list of valid indices for 'strings'.")
    if output_format not in ['string', 'array']:
        raise ValueError("'output_format' must be either 'string' or 'array'.")
    if case_transformation not in ['none', 'uppercase', 'lowercase', 'capitalize']:
        raise ValueError("'case_transformation' must be one of 'none', 'uppercase', 'lowercase', 'capitalize'.")

    # Handle duplicates if required
    if handle_duplicates:
        strings = list(dict.fromkeys(strings))

    # Apply order if specified
    if order:
        strings = [strings[i] for i in order]

    # Apply transformations
    transformed_strings = []
    for s in strings:
        if trim_whitespace:
            s = s.strip()
        if case_transformation == 'uppercase':
            s = s.upper()
        elif case_transformation == 'lowercase':
            s = s.lower()
        elif case_transformation == 'capitalize':
            s = s.capitalize()
        transformed_strings.append(s)

    # Concatenate strings
    result = separator.join(transformed_strings)

    # Return result based on output_format
    if output_format == 'array':
        return transformed_strings
    return result

