    # Additional logic can be added here to handle other information types and parameters", "def date_calculator(start_date, interval, output_format='YYYY-MM-DDTHH:MM:SS', time_zone=None, business_days_only=False):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        start_datetime = datetime.fromisoformat(start_date)
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DDTHH:MM:SS with optional timezone.'}

    # Validate interval
    if 'value' not in interval or 'unit' not in interval:
        return {'error': 'Interval must have both value and unit.'}
    if interval['unit'] not in ['minutes', 'hours', 'days', 'weeks', 'months', 'years']:
        return {'error': 'Invalid interval unit. Supported units are minutes, hours, days, weeks, months, years.'}

    # Apply interval
    if interval['unit'] == 'minutes':
        delta = timedelta(minutes=interval['value'])
    elif interval['unit'] == 'hours':
        delta = timedelta(hours=interval['value'])
    elif interval['unit'] == 'days':
        delta = timedelta(days=interval['value'])
    elif interval['unit'] == 'weeks':
        delta = timedelta(weeks=interval['value'])
    elif interval['unit'] == 'months':
        delta = relativedelta(months=interval['value'])
    elif interval['unit'] == 'years':
        delta = relativedelta(years=interval['value'])

    # Calculate new date
    new_date = start_datetime + delta

    # Handle time zone
    if time_zone:
        try:
            tz = pytz.timezone(time_zone)
            new_date = new_date.astimezone(tz)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Invalid time zone specified.'}

    # Format output
    if output_format == 'YYYY-MM-DDTHH:MM:SS':
        formatted_date = new_date.strftime('%Y-%m-%dT%H:%M:%S')
    elif output_format == 'MM-DD-YYYYTHH:MM:SS':
        formatted_date = new_date.strftime('%m-%d-%YT%H:%M:%S')
    elif output_format == 'DD-MM-YYYYTHH:MM:SS':
        formatted_date = new_date.strftime('%d-%m-%YT%H:%M:%S')
    else:
        return {'error': 'Invalid output format specified.'}

    return {'result': formatted_date}

# Example usage based on the question
result = date_calculator(
    start_date='1982-01-22T00:00:00',
    interval={'value': 1, 'unit': 'months'}
)
print(result)  # Expected output: {'result': '1982-02-22T00:00:00'}"]

