            elif output_format == 'ascii':
                return str(ord(char))
            elif output_format == 'unicode':
                return f'U+{ord(char):04X}'
            elif output_format == 'hex':
                return hex(ord(char))

        elif handle_non_alpha == 'error':
            raise ValueError('Non-alphabetic character encountered at the start of the string.')

