    # Validate input
    if not input:
        raise ValueError('Input must be at least one character long.')
    if output_format not in ['binary_string', 'binary_list', 'binary_array']:
        raise ValueError('Invalid output format specified.')
    if encoding not in ['utf-8', 'ascii']:
        raise ValueError('Invalid encoding specified.')
    if bit_length not in [8, 16, 32]:
        raise ValueError('Invalid bit length specified.')

    # Convert character(s) to binary
    binary_codes = []
    for char in input:
        if encoding == 'ascii':
            binary_code = format(ord(char), f'0{bit_length}b')
        else:  # utf-8
            binary_code = ''.join(format(byte, f'0{bit_length}b') for byte in char.encode('utf-8'))
        if include_prefix:
            binary_code = '0b' + binary_code
        binary_codes.append(binary_code)

    # Format output
    if output_format == 'binary_string':
        return delimiter.join(binary_codes)
    elif output_format == 'binary_list':
        return binary_codes
    elif output_format == 'binary_array':
        return binary_codes  # In Python, lists can serve as arrays

