# print(result)  # Expected output: '19 March 1857'", "def closest_palindrome_year(year, search_range=1000, output_format='year', search_direction='both'):
    # Helper function to check if a year is a palindrome
    def is_palindrome(y):
        return str(y) == str(y)[::-1]

    # Validate input parameters
    if not isinstance(year, int):
        return {'error': 'Year must be an integer.'}
    if not isinstance(search_range, int) or search_range <= 0:
        return {'error': 'Search range must be a positive integer.'}
    if output_format not in ['year', 'difference', 'both']:
        return {'error': "Output format must be 'year', 'difference', or 'both'."}
    if search_direction not in ['past', 'future', 'both']:
        return {'error': "Search direction must be 'past', 'future', or 'both'."}

    closest_year = None
    closest_difference = float('inf')

    # Search for palindrome years
    for i in range(1, search_range + 1):
        if search_direction in ['future', 'both']:
            future_year = year + i
            if is_palindrome(future_year):
                if i < closest_difference:
                    closest_year = future_year
                    closest_difference = i

        if search_direction in ['past', 'both']:
            past_year = year - i
            if is_palindrome(past_year):
                if i < closest_difference:
                    closest_year = past_year
                    closest_difference = i

    # Prepare the output based on the requested format
    if output_format == 'year':
        return closest_year
    elif output_format == 'difference':
        return closest_difference
    elif output_format == 'both':
        return {'year': closest_year, 'difference': closest_difference}

    return {'error': 'Unexpected error occurred.'}

# Example usage
# closest_palindrome_year(1857) should return 1881 based on the question and answer provided."]

["def tv_show_character_lookup(character_name: str = None, actor_name: str = None, output_format: str = 'text', genre_filter: str = None, year_filter: int = None, network_filter: str = None):
    """
    Searches for TV shows associated with a given character or actor.

    Parameters:
    - character_name (str): The name of the character to look up.
    - actor_name (str): The name of the actor to look up.
