    """
    Extracts the year from a given date string.

    Parameters:
    - date_input (str): The date string from which the year is to be extracted.
    - date_format (str, optional): The format of the date string.
    - error_handling (str): Determines error handling strategy ('strict', 'lenient', 'custom').
    - timezone (str, optional): The timezone for date parsing.
    - locale (str, optional): The locale for date parsing.
    - output_format (str): Specifies the format of the output ('year', 'full_date').

    Returns:
    - str: The extracted year or the full date string based on output_format.
    """
    from datetime import datetime
    import pytz

    try:
        # Handle timezone
        tz = pytz.timezone(timezone) if timezone else pytz.UTC

        # Parse the date
        if date_format:
            date_obj = datetime.strptime(date_input, date_format)
        else:
            date_obj = datetime.fromisoformat(date_input)

        # Apply timezone
        date_obj = date_obj.astimezone(tz)

        # Return based on output_format
        if output_format == 'year':
            return str(date_obj.year)
        elif output_format == 'full_date':
            return date_obj.isoformat()
    except Exception as e:
        if error_handling == 'strict':
            raise ValueError(f"Invalid date input: {e}")
        elif error_handling == 'lenient':
            return 'Invalid date, defaulting to 1970' if output_format == 'year' else '1970-01-01T00:00:00+00:00'
        elif error_handling == 'custom':
            return f"Custom error handling: {e}"

