    """
    if not full_name:
        raise ValueError("The 'full_name' parameter is required.")
    if name_format not in ['western', 'eastern', 'custom']:
        raise ValueError("Invalid 'name_format'. Must be 'western', 'eastern', or 'custom'.")

    # Normalize the full name based on case sensitivity
    if not case_sensitive:
        full_name = full_name.lower()

    # Handle prefixes and suffixes if required
    prefixes = ['dr.', 'mr.', 'ms.'] if handle_prefixes else []
    suffixes = ['jr.', 'sr.', 'iii'] if handle_suffixes else []

    # Remove prefixes
    for prefix in prefixes:
        if full_name.startswith(prefix):
            full_name = full_name[len(prefix):].strip()

    # Remove suffixes
    for suffix in suffixes:
        if full_name.endswith(suffix):
            full_name = full_name[:-len(suffix)].strip()

    # Split the name based on the format
    if name_format == 'western':
        parts = full_name.split()
        last_name = parts[-1] if parts else ''
    elif name_format == 'eastern':
        parts = full_name.split()
        last_name = parts[0] if parts else ''
    elif name_format == 'custom' and custom_delimiter:
        parts = full_name.split(custom_delimiter)
        last_name = parts[-1] if parts else ''
    elif name_format == 'custom' and multiple_delimiters:
        import re
        pattern = '|'.join(map(re.escape, multiple_delimiters))
        parts = re.split(pattern, full_name)
        last_name = parts[-1] if parts else ''
    else:
        raise ValueError("Invalid configuration for 'custom' name format.")

    # Include middle names if required
    if include_middle_names and len(parts) > 2:
        last_name = ' '.join(parts[1:])

    return last_name

