    # Helper function to check if a year is a palindrome
    def is_palindrome(y):
        return str(y) == str(y)[::-1]

    # Validate input parameters
    if not isinstance(year, int):
        raise ValueError('Year must be an integer.')
    if not isinstance(return_multiple, bool):
        raise ValueError('Return_multiple must be a boolean.')
    if not isinstance(search_range, int) or search_range <= 0:
        raise ValueError('Search_range must be a positive integer.')
    if not isinstance(return_all_within_range, bool):
        raise ValueError('Return_all_within_range must be a boolean.')

    # Initialize variables
    closest_year = None
    closest_distance = float('inf')
    palindrome_years = []

    # Search for palindrome years within the range
    for offset in range(-search_range, search_range + 1):
        candidate_year = year + offset
        if is_palindrome(candidate_year):
            distance = abs(offset)
            if return_all_within_range:
                palindrome_years.append(candidate_year)
            elif distance < closest_distance:
                closest_year = candidate_year
                closest_distance = distance
                palindrome_years = [candidate_year]
            elif return_multiple and distance == closest_distance:
                palindrome_years.append(candidate_year)

    # Return results based on parameters
    if return_all_within_range:
        return palindrome_years
    return palindrome_years if return_multiple else palindrome_years[0]

