    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Validate optional parameters
    if name_format not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid name_format. Must be one of: western, eastern, custom.'}
    if prefix_handling not in ['ignore', 'include']:
        return {'error': 'Invalid prefix_handling. Must be one of: ignore, include.'}
    if suffix_handling not in ['ignore', 'include']:
        return {'error': 'Invalid suffix_handling. Must be one of: ignore, include.'}

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handle prefix if included
    if prefix_handling == 'include' and len(name_parts) > 1:
        first_name_index = 1
    else:
        first_name_index = 0

    # Extract first name based on the name format
    if name_format == 'western':
        first_name = name_parts[first_name_index]
    elif name_format == 'eastern':
        first_name = name_parts[-1]
    else:  # custom
        first_name = name_parts[first_name_index]

    # Include middle name if specified
    if include_middle_name and len(name_parts) > first_name_index + 1:
        first_name += ' ' + name_parts[first_name_index + 1]

    # Handle suffix if included
    if suffix_handling == 'include' and len(name_parts) > first_name_index + 2:
        first_name += ' ' + name_parts[first_name_index + 2]

    return {'first_name': first_name}

