    import datetime
    import pytz
    from dateutil import parser

    # Error handling for unsupported date formats
    if date_format not in ['YYYY-MM-DD', 'DD-MM-YYYY', 'MM-DD-YYYY']:
        return {'error': 'Unsupported date format'}

    # Error handling for unsupported output formats
    if output_format not in ['full', 'abbreviated', 'numeric']:
        return {'error': 'Unsupported output format'}

    # Error handling for unsupported calendar systems
    if calendar_system not in ['gregorian', 'julian']:
        return {'error': 'Unsupported calendar system'}

    # Parse the date according to the specified format
    try:
        if date_format == 'YYYY-MM-DD':
            parsed_date = datetime.datetime.strptime(date, '%Y-%m-%d')
        elif date_format == 'DD-MM-YYYY':
            parsed_date = datetime.datetime.strptime(date, '%d-%m-%Y')
        elif date_format == 'MM-DD-YYYY':
            parsed_date = datetime.datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return {'error': 'Invalid date'}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        parsed_date = tz.localize(parsed_date)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone'}

    # Calculate the day of the week
    if calendar_system == 'gregorian':
        day_of_week = parsed_date.weekday()  # Monday is 0 and Sunday is 6
    elif calendar_system == 'julian':
        # Julian calendar adjustment
        julian_date = parsed_date.toordinal() - 13
        day_of_week = (julian_date + 1) % 7  # Julian calendar: Monday is 0

    # Convert to the desired output format
    days_full = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    days_abbr = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']

    if output_format == 'full':
        return {'day_of_week': days_full[day_of_week]}
    elif output_format == 'abbreviated':
        return {'day_of_week': days_abbr[day_of_week]}
    elif output_format == 'numeric':
        return {'day_of_week': day_of_week}

# Example usage
result = day_of_week_calculator('1988-03-09', output_format='numeric')
print(result)  # Output: {'day_of_week': 3}"]

["def game_character_lookup(sports_figure: str, role: str, game_type: str, release_year: int = None, platform: str = None, developer: str = None, output_format: str = 'list') -> dict:
