# print(result)  # Expected output: {'last_name': 'al-Dawla'}", "def combined_length_calculator(input, ignore_characters=[], ignore_position=[], output_format='integer', case_sensitive=False, whitespace_handling='include', delimiter=' '):
    # Error handling for required input
    if not isinstance(input, list) or len(input) < 2:
        return {'error': 'Input must be an array of at least two strings.'}

    # Initialize total length
    total_length = 0

    # Process each string in the input
    for string in input:
        # Handle case sensitivity
        if not case_sensitive:
            string = string.lower()
            ignore_characters = [char.lower() for char in ignore_characters]

        # Handle whitespace
        if whitespace_handling == 'trim':
            string = string.strip()
        elif whitespace_handling == 'exclude':
            string = ''.join(string.split())

        # Ignore specified positions
        if 'first' in ignore_position and len(string) > 0:
            string = string[1:]
        if 'last' in ignore_position and len(string) > 0:
            string = string[:-1]

        # Remove ignored characters
        for char in ignore_characters:
            string = string.replace(char, '')

        # Add length of processed string to total
        total_length += len(string)

    # Return result in specified format
    if output_format == 'integer':
        return total_length
    elif output_format == 'text':
        return delimiter.join([str(len(s)) for s in input])
    else:
        return {'error': 'Invalid output format specified.'}

