    """
    Extracts the last name from a full name string based on the specified naming convention.

    Parameters:
    - full_name (str): The full name from which the last name is to be extracted.
    - name_structure (str): The naming convention to be used for extraction.
    - custom_pattern (str): A custom pattern for extracting the last name, used only if 'name_structure' is 'custom'.
    - error_handling (str): Defines the behavior when encountering invalid inputs.

    Returns:
    - str: The extracted last name.
    """
    try:
        if name_structure == 'western':
            # Western convention: last name is the final part
            return full_name.split()[-1]
        elif name_structure == 'eastern':
            # Eastern convention: last name is the first part
            return full_name.split()[0]
        elif name_structure == 'arabic':
            # Arabic convention: last name is the second part
            parts = full_name.split()
            return parts[1] if len(parts) > 1 else ''
        elif name_structure == 'hispanic':
            # Hispanic convention: compound last names
            parts = full_name.split()
            return ' '.join(parts[-2:]) if len(parts) > 1 else parts[-1]
        elif name_structure == 'custom':
            # Custom pattern extraction
            import re
            match = re.search(custom_pattern, full_name)
            if match:
                return match.group(0)
            else:
                if error_handling == 'warn':
                    print('Warning: Custom pattern did not match any part of the name.')
                elif error_handling == 'strict':
                    raise ValueError('Custom pattern did not match any part of the name.')
                return ''
        else:
            if error_handling == 'warn':
                print('Warning: Invalid name structure provided.')
            elif error_handling == 'strict':
                raise ValueError('Invalid name structure provided.')
            return ''
    except Exception as e:
        if error_handling == 'warn':
            print(f'Warning: {str(e)}')
        elif error_handling == 'strict':
            raise
        return ''

