    # Define common prefixes and suffixes
    prefixes = ['Mr.', 'Mrs.', 'Ms.', 'Dr.', 'Prof.']
    suffixes = ['Jr.', 'Sr.', 'II', 'III', 'IV']

    # Split the full name by the delimiter
    name_parts = full_name.split(delimiter)

    # Remove prefixes if ignore_prefixes is True
    if ignore_prefixes:
        name_parts = [part for part in name_parts if part not in prefixes]

    # Handle suffixes based on suffix_handling
    if suffix_handling == 'ignore':
        name_parts = [part for part in name_parts if part not in suffixes]
    elif suffix_handling == 'separate':
        name_parts = [part for part in name_parts if part not in suffixes]
        suffix = [part for part in full_name.split(delimiter) if part in suffixes]
    else:
        suffix = []

    # Extract first name and optionally middle name
    if include_middle_name and len(name_parts) > 1:
        first_name = ' '.join(name_parts[:2])
    else:
        first_name = name_parts[0] if name_parts else ''

    # Return the result
    result = {'first_name': first_name}
    if suffix_handling == 'separate' and suffix:
        result['suffix'] = suffix[0]

    return result

