        max_length = filter_criteria.get('max_length', float('inf'))
        allowed_characters = filter_criteria.get('allowed_characters', None)
        input = [s for s in input if min_length <= len(s) <= max_length]
        if allowed_characters is not None:
            input = [''.join(c for c in s if c in allowed_characters) for s in input]

    # Process each string in input
    sorted_strings = []
    for s in input:
        # Filter non-alphabetic characters if required
        if ignore_non_alpha:
            s = ''.join(filter(str.isalpha, s))

        # Sort characters
        if not case_sensitive:
            s = s.lower()
        sorted_chars = sorted(s, reverse=(sort_order == 'descending'))
        sorted_strings.append(''.join(sorted_chars))

    return {'sorted_strings': sorted_strings}

# Example usage
