["def contribution_finder(contributor_name: str, genre: str = 'healthy lifestyle', publication_date: str = None, magazine_title: str = None, output_format: str = 'list') -> dict:
    """
    Identify magazine contributions by a specific individual with filtering options.

    :param contributor_name: The name of the contributor whose magazine contributions are to be identified.
    :param genre: The genre of the magazine to filter contributions, default is 'healthy lifestyle'.
    :param publication_date: The publication date to filter contributions, in YYYY-MM-DD format.
    :param magazine_title: The title of the magazine to filter contributions.
    :param output_format: The format of the output. 'list' provides magazine names only, 'detailed' includes additional contribution details, 'summary' provides a brief overview of contributions.
    :return: A dictionary containing the filtered contributions or an error message.
    """
    # Simulated database of contributions
    contributions_db = [
        {'contributor_name': 'Georgia Rickard', 'genre': 'healthy lifestyle', 'publication_date': '2023-01-15', 'magazine_title': 'Prevention', 'details': 'Article on mental health.'},
        {'contributor_name': 'Georgia Rickard', 'genre': 'travel', 'publication_date': '2023-02-20', 'magazine_title': 'Travel Weekly', 'details': 'Feature on sustainable tourism.'}
    ]

    # Validate genre
    valid_genres = ['healthy lifestyle', 'fitness', 'nutrition', 'wellness', 'technology', 'travel', 'fashion', 'business']
    if genre not in valid_genres:
        return {'error': 'Invalid genre specified.'}

    # Validate output format
    valid_formats = ['list', 'detailed', 'summary']
    if output_format not in valid_formats:
        return {'error': 'Invalid output format specified.'}

    # Filter contributions
    filtered_contributions = [
        contrib for contrib in contributions_db
        if contrib['contributor_name'] == contributor_name and
           (genre is None or contrib['genre'] == genre) and
           (publication_date is None or contrib['publication_date'] == publication_date) and
           (magazine_title is None or contrib['magazine_title'] == magazine_title)
    ]

    # Format output
    if output_format == 'list':
        return {'contributions': [contrib['magazine_title'] for contrib in filtered_contributions]}
    elif output_format == 'detailed':
        return {'contributions': filtered_contributions}
    elif output_format == 'summary':
        return {'summary': f"Found {len(filtered_contributions)} contributions by {contributor_name}."}

    # Default case
    return {'error': 'Unexpected error occurred.'}

# Example usage
