    return 'Information not found.'", "def date_difference_calculator(start_date, end_date, date_format='YYYY-MM-DD', output_format='integer', time_zone='UTC', business_days_only=False, holidays=[]):
    from datetime import datetime, timedelta
    import pytz
    from dateutil import parser

    # Helper function to parse dates based on the provided format
    def parse_date(date_str, date_format):
        try:
            if date_format == 'YYYY-MM-DD':
                return datetime.strptime(date_str, '%Y-%m-%d')
            elif date_format == 'DD/MM/YYYY':
                return datetime.strptime(date_str, '%d/%m/%Y')
            elif date_format == 'MM-DD-YYYY':
                return datetime.strptime(date_str, '%m-%d-%Y')
            else:
                raise ValueError('Unsupported date format')
        except ValueError as e:
            raise ValueError(f'Invalid date format: {e}')

    # Parse the start and end dates
    try:
        start_date_parsed = parse_date(start_date, date_format)
        end_date_parsed = parse_date(end_date, date_format)
    except ValueError as e:
        return {'error': str(e)}

    # Ensure start_date is before end_date
    if start_date_parsed > end_date_parsed:
        return {'error': 'Start date must be before end date'}

    # Calculate the difference in days
    delta = end_date_parsed - start_date_parsed
    total_days = delta.days

    # Adjust for business days if required
    if business_days_only:
        business_days = 0
        current_date = start_date_parsed
        while current_date <= end_date_parsed:
            if current_date.weekday() < 5 and current_date.strftime('%Y-%m-%d') not in holidays:
                business_days += 1
            current_date += timedelta(days=1)
        total_days = business_days

    # Return the result based on the output format
    if output_format == 'integer':
        return {'days': total_days}
    elif output_format == 'text':
        return {'days': f'The total number of days is {total_days}.'}
    elif output_format == 'detailed':
        years, remainder = divmod(total_days, 365)
        months, days = divmod(remainder, 30)
        return {'days': total_days, 'detailed': f'{years} years, {months} months, and {days} days'}
    else:
        return {'error': 'Unsupported output format'}"]

