["def monarch_reign_analyzer(monarch_list, output_format='name_only', filter_criteria=None):
    from datetime import datetime

    def parse_date(date_str):
        if date_str.lower() == 'present':
            return datetime.now()
        return datetime.strptime(date_str, '%Y-%m-%d')

    def calculate_reign_duration(start_date, end_date):
        start = parse_date(start_date)
        end = parse_date(end_date)
        return (end - start).days

    # Validate input
    if not isinstance(monarch_list, list) or len(monarch_list) == 0:
        raise ValueError('monarch_list must be a non-empty list of monarchs.')
    if output_format not in ['name_only', 'detailed', 'full_analysis']:
        raise ValueError('Invalid output_format. Choose from name_only, detailed, full_analysis.')

    # Apply filters if any
    if filter_criteria:
        if 'time_period' in filter_criteria:
            start_filter = parse_date(filter_criteria['time_period']['start'])
            end_filter = parse_date(filter_criteria['time_period']['end'])
            monarch_list = [m for m in monarch_list if parse_date(m['start_date']) <= end_filter and parse_date(m['end_date']) >= start_filter]
        if 'region' in filter_criteria:
            monarch_list = [m for m in monarch_list if m.get('region') == filter_criteria['region']]
        if 'dynasty' in filter_criteria:
            monarch_list = [m for m in monarch_list if m.get('dynasty') == filter_criteria['dynasty']]

    # Find the longest reigning monarch
    longest_reign = 0
    longest_reigning_monarch = None
    for monarch in monarch_list:
        reign_duration = calculate_reign_duration(monarch['start_date'], monarch['end_date'])
        if reign_duration > longest_reign:
            longest_reign = reign_duration
            longest_reigning_monarch = monarch

    # Prepare output
    if longest_reigning_monarch is None:
        return 'No monarchs found after applying filters.'

    if output_format == 'name_only':
        return longest_reigning_monarch['name']
    elif output_format == 'detailed':
        return {
            'name': longest_reigning_monarch['name'],
            'duration_days': longest_reign
        }
    elif output_format == 'full_analysis':
