["def entertainment_title_matcher(artist_name: str, album_number: int, film_year: int = None, title_format: str = 'exact', genre: str = None, language: str = 'any', include_tv_series: bool = False):
    """
    Matches album titles with film or TV series titles based on the specified parameters.
    """
    # Validate parameters
    if not isinstance(artist_name, str) or not artist_name:
        return {'error': 'Invalid artist_name. It must be a non-empty string.'}
    if not isinstance(album_number, int) or album_number <= 0:
        return {'error': 'Invalid album_number. It must be a positive integer.'}
    if film_year is not None and (not isinstance(film_year, int) or film_year < 0):
        return {'error': 'Invalid film_year. It must be a non-negative integer or None.'}
    if title_format not in ['exact', 'contains', 'starts_with', 'ends_with']:
        return {'error': 'Invalid title_format. It must be one of: exact, contains, starts_with, ends_with.'}
    if genre is not None and not isinstance(genre, str):
        return {'error': 'Invalid genre. It must be a string or None.'}
    if not isinstance(language, str):
        return {'error': 'Invalid language. It must be a string.'}
    if not isinstance(include_tv_series, bool):
        return {'error': 'Invalid include_tv_series. It must be a boolean.'}

    # Simulated database of titles
    albums = {
        'David Gates': ['First', 'Second', 'Goodbye Girl'],
    }
    films = {
        1977: ['Goodbye Girl', 'Star Wars', 'Close Encounters of the Third Kind'],
    }

    # Fetch the album title
    try:
        album_title = albums[artist_name][album_number - 1]
    except (KeyError, IndexError):
        return {'error': 'Album not found for the given artist and album number.'}

    # Match the album title with film titles
    matched_titles = []
    for year, titles in films.items():
        if film_year is not None and year != film_year:
            continue
        for title in titles:
            if title_format == 'exact' and album_title == title:
                matched_titles.append(title)
            elif title_format == 'contains' and album_title in title:
                matched_titles.append(title)
            elif title_format == 'starts_with' and title.startswith(album_title):
                matched_titles.append(title)
            elif title_format == 'ends_with' and title.endswith(album_title):
                matched_titles.append(title)

    return {'matched_titles': matched_titles}

# Example usage
result = entertainment_title_matcher('David Gates', 3, film_year=1977)
print(result)  # Expected output: {'matched_titles': ['Goodbye Girl']}", "def film_director_lookup(film_title: str, year: int = None, fuzzy_matching: bool = True, genre: str = None, language: str = None, detailed_output: bool = False):
