# print(biographical_info_retriever(name='Joseph-Stanislas Perrault', info_type='date_of_birth'))", "def date_calculator(start_date: str, days_offset: int, end_date: str = None, date_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    import pytz

    # Validate and parse the start_date
    try:
        if date_format == 'YYYY-MM-DD':
            date_obj = datetime.strptime(start_date, '%Y-%m-%d')
        elif date_format == 'MM/DD/YYYY':
            date_obj = datetime.strptime(start_date, '%m/%d/%Y')
        elif date_format == 'DD-MM-YYYY':
            date_obj = datetime.strptime(start_date, '%d-%m-%Y')
        else:
            raise ValueError('Unsupported date format')
    except ValueError as e:
        return f"Error: Invalid start_date format - {str(e)}"

    # Apply the time zone
    try:
        tz = pytz.timezone(time_zone)
        date_obj = tz.localize(date_obj)
    except pytz.UnknownTimeZoneError:
        return "Error: Unknown time zone"

    # Calculate the new date
    try:
        new_date_obj = date_obj + timedelta(days=days_offset)
    except Exception as e:
        return f"Error: Unable to calculate new date - {str(e)}"

    # Format the new date
    if date_format == 'YYYY-MM-DD':
        new_date_str = new_date_obj.strftime('%Y-%m-%d')
    elif date_format == 'MM/DD/YYYY':
        new_date_str = new_date_obj.strftime('%m/%d/%Y')
    elif date_format == 'DD-MM-YYYY':
        new_date_str = new_date_obj.strftime('%d-%m-%Y')
    else:
        return "Error: Unsupported date format"

    return new_date_str

# Example usage based on the question
result = date_calculator(start_date='1846-05-13', days_offset=-8)
print(result)  # Expected output: '1846-05-05'"]

