    else:
        # Default to text format
        return f"Name: {educational_info['name']}, Institution: {educational_info['institution']}, Degree: {educational_info['degree']}, Years: {educational_info['years']}"", "def longest_word_finder(input_string, ignore_punctuation=True, case_sensitive=False, handle_ties='first', custom_delimiters=[' '], include_numbers=False, output_details=False):
    import re

    # Error handling for invalid 'handle_ties' value
    if handle_ties not in ['first', 'last', 'all']:
        return {'error': "Invalid value for 'handle_ties'. Must be 'first', 'last', or 'all'."}

    # Define delimiters
    delimiters = '|'.join(map(re.escape, custom_delimiters))

    # Prepare the input string
    if not case_sensitive:
        input_string = input_string.lower()

    # Remove punctuation if needed
    if ignore_punctuation:
        input_string = re.sub(r'[\W_]+', ' ', input_string)

    # Split the input string into words
    words = re.split(delimiters, input_string)

    # Filter out numbers if include_numbers is False
    if not include_numbers:
        words = [word for word in words if not word.isdigit()]

    # Find the longest word(s)
    max_length = 0
    longest_words = []
    for word in words:
        if len(word) > max_length:
            max_length = len(word)
            longest_words = [word]
        elif len(word) == max_length:
            longest_words.append(word)

    # Handle ties
    if handle_ties == 'first':
        result = longest_words[0] if longest_words else ''
    elif handle_ties == 'last':
        result = longest_words[-1] if longest_words else ''
    else:  # 'all'
        result = longest_words

    # Prepare detailed output if requested
    if output_details:
        detailed_output = [{'word': word, 'length': len(word), 'position': input_string.find(word)} for word in longest_words]
        return {'longest_word': result, 'details': detailed_output}

    return {'longest_word': result}

