["def publication_info_retriever(publication_name: str, information_type: list, output_format: str = 'text', publication_year_filter: int = None, publication_type_filter: str = None):
    """
    Retrieve comprehensive information about a publication.

    :param publication_name: The name of the publication for which information is being requested.
